
document.addEventListener('DOMContentLoaded',()=>{
 try{
  initDB();
  // Never block the portal UI on an optional cloud sync. LocalStorage is the immediate
  // source of truth; Supabase reconciliation runs in the background.
  const u=currentUser();
  if(document.body.dataset.auth==='login'){initLogin();return}
  const role=document.body.dataset.role;
  const user=requireAuth(role); if(!user)return;
  setupLayout(user); setupFloating(role); initPage(role,user);
 }catch(error){
  console.error('EAD portal boot error:',error);
  const root=document.getElementById('pageRoot');
  if(root)root.innerHTML=`<div class="card" style="max-width:760px;margin:40px auto;padding:28px"><h2 style="margin-top:0">EAD University Portal could not load this module</h2><p class="muted">The application has recovered from a JavaScript/data error instead of leaving a blank screen.</p><div class="notice danger"><b>Error:</b> ${esc(error?.message||'Unknown application error')}</div><div class="actions" style="margin-top:16px"><button class="btn btn-primary" onclick="location.reload()">Reload Portal</button><a class="btn btn-light" href="../login.html">Back to Login</a></div></div>`;
  window.hidePortalLoading?.();
 }
});
window.addEventListener('ead-cloud-refresh',()=>{
 try{const u=currentUser();const role=document.body.dataset.role;if(u&&role&&document.body.dataset.auth==='protected')initPage(role,u)}catch(e){console.warn('Cloud refresh skipped:',e)}
});
function initLogin(){
 const form=document.getElementById('loginForm'),err=document.getElementById('loginError'),btn=document.getElementById('loginBtn');
 const email=document.getElementById('email'),password=document.getElementById('password'),role=document.getElementById('role');
 const roleLabel=document.getElementById('selectedRole'),roleHint=document.getElementById('roleHint');
 const roleInfo={admin:['Admin','Full system access'],teacher:['Teacher','Schedules & student groups'],student:['Student','Personal schedule access']};
 const selectRole=(r,mail)=>{role.value=r; if(mail)email.value=mail; const info=roleInfo[r]||roleInfo.admin; roleLabel.textContent=info[0];roleHint.textContent=info[1];document.querySelectorAll('[data-demo]').forEach(x=>x.classList.toggle('active',x.dataset.role===r));email.focus();};
 document.getElementById('togglePassword')?.addEventListener('click',()=>{const show=password.type==='password';password.type=show?'text':'password';const b=document.getElementById('togglePassword');b.textContent=show?'◉':'◉';b.setAttribute('aria-label',show?'Hide password':'Show password');});
 form?.addEventListener('submit',e=>{e.preventDefault();err.style.display='none';
  if(!email.value.trim()||!email.validity.valid){err.textContent='Please enter a valid EAD University email address.';err.style.display='block';email.focus();return}
  if(!password.value){err.textContent='Please enter your password.';err.style.display='block';password.focus();return}
  btn.disabled=true;btn.textContent='Signing in…';
  setTimeout(()=>{const ok=login(email.value,password.value,role.value,false);if(ok)location.href=roleHome(role.value);else{err.textContent='Invalid credentials or inactive account. Please verify your selected role and password.';err.style.display='block';btn.disabled=false;btn.textContent='Sign in'}},450);
 });
 document.querySelectorAll('[data-demo]').forEach(b=>b.addEventListener('click',()=>selectRole(b.dataset.role,b.dataset.demo)));
 // Complete Supabase OAuth callback: after Google returns to this page, map the authenticated email to an EAD role and continue to the correct dashboard.
 (async()=>{try{if(!window.EAD_SUPABASE?.auth)return;const {data:{session}}=await window.EAD_SUPABASE.auth.getSession();const mail=session?.user?.email?.toLowerCase();if(!mail)return;const aliases={'admin@ead.edu.pk':'admin@ead.edu','teacher@ead.edu.pk':'teacher@ead.edu','student@ead.edu.pk':'student@ead.edu'};const mapped=aliases[mail]||mail;const account=getData('users').find(x=>String(x.email||'').toLowerCase()===mapped);if(!account){err.textContent='Your Google account is authenticated, but it is not linked to an EAD University portal role.';err.style.display='block';return;}sessionStorage.setItem('eadSession',account.id);location.replace(roleHome(account.role));}catch(ex){console.warn('Supabase OAuth callback could not be completed.',ex)}})();
 const passkeyBtn=document.getElementById('passkeySignIn');
 if(passkeyBtn&&getData('settings')?.passkeyEnabled===false){passkeyBtn.style.display='none';}
 passkeyBtn?.addEventListener('click',async()=>{const note=document.getElementById('authProviderNote');try{if(!window.PublicKeyCredential)throw new Error('Passkeys are not supported by this browser.');note.textContent='Checking for your EAD University passkey…';passkeyBtn.disabled=true;const r=await fetch('/api/auth/passkey/options',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:email.value.trim(),role:role.value})});if(!r.ok)throw new Error((await r.json()).error||'Unable to start passkey sign-in.');const opts=await r.json();const transactionId=opts.transactionId;const fromB64=v=>Uint8Array.from(atob(v.replace(/-/g,'+').replace(/_/g,'/')+('='.repeat((4-(v.length%4))%4))),c=>c.charCodeAt(0));const toB64=b=>btoa(String.fromCharCode(...new Uint8Array(b))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');const publicKey={...opts};delete publicKey.transactionId;publicKey.challenge=fromB64(publicKey.challenge);publicKey.allowCredentials=(publicKey.allowCredentials||[]).map(c=>({...c,id:fromB64(c.id)}));const cred=await navigator.credentials.get({publicKey});const payload={id:cred.id,rawId:toB64(cred.rawId),type:cred.type,response:{authenticatorData:toB64(cred.response.authenticatorData),clientDataJSON:toB64(cred.response.clientDataJSON),signature:toB64(cred.response.signature),userHandle:cred.response.userHandle?toB64(cred.response.userHandle):null}};const verify=await fetch('/api/auth/passkey/verify',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({transactionId,response:payload})});const out=await verify.json();if(!verify.ok)throw new Error(out.error||'Passkey sign-in failed.');const aliases={'admin@ead.edu.pk':'admin@ead.edu','teacher@ead.edu.pk':'teacher@ead.edu','student@ead.edu.pk':'student@ead.edu'};const account=getData('users').find(x=>String(x.email||'').toLowerCase()===(aliases[String(out.user.email||'').toLowerCase()]||String(out.user.email||'').toLowerCase())&&x.role===out.user.role);if(!account)throw new Error('The passkey account is not linked to this browser portal.');sessionStorage.setItem('eadSession',account.id);if(out.token)sessionStorage.setItem('eadApiToken',out.token);location.href=roleHome(account.role);}catch(ex){note.textContent=ex.name==='TypeError'?'Passkey sign-in needs the EAD server running (npm start) and this page must be opened from that server.':(ex.message||'Passkey sign-in could not be completed.');passkeyBtn.disabled=false;}});
 const modal=document.getElementById('forgotModal'),open=document.getElementById('forgotPassword'),close=document.getElementById('closeForgot'),send=document.getElementById('sendReset');
 const closeModal=()=>{modal?.classList.remove('open');modal?.setAttribute('aria-hidden','true')};
 open?.addEventListener('click',()=>{modal.classList.add('open');modal.setAttribute('aria-hidden','false');document.getElementById('resetEmail').focus()});
 close?.addEventListener('click',closeModal);modal?.addEventListener('click',e=>{if(e.target===modal)closeModal()});
 send?.addEventListener('click',()=>{const r=document.getElementById('resetEmail');if(!r.value||!r.validity.valid){r.focus();return}document.getElementById('resetMessage').style.display='block'});
}
function initPage(role,user){
 const p=document.body.dataset.page;
 const fn={
 dashboard:renderDashboard,students:renderStudents,teachers:renderTeachers,departments:renderDepartments,programs:renderPrograms,
 subjects:renderSubjects,classes:renderClasses,timetable:renderTimetable,attendance:renderAttendance,
 assignments:renderAssignments,exams:renderExams,results:renderResults,fees:renderFees,announcements:renderAnnouncements,
 messages:renderMessages,notifications:renderNotifications,materials:renderMaterials,reports:renderReports,settings:renderSettings,profile:renderProfile,
 courses:renderCourses,teacherStudents:renderTeacherStudents,teachersStudent:renderStudentTeachers
 }[p];
 if(fn)fn(role,user);
 else renderPlaceholder(role,user,p);
}
function renderDashboard(role,u){
 const root=document.getElementById('pageRoot'),d=db();
 if(!d||!root){return} 
 if(role==='admin'){root.innerHTML=adminDash(d);bindDashboardAdmin();if(window.mountDashboardScaffolding)mountDashboardScaffolding(role,u);return}
 if(role==='teacher'){root.innerHTML=teacherDash(d,u);if(window.mountDashboardScaffolding)mountDashboardScaffolding(role,u);return}
 root.innerHTML=studentDash(d,u);if(window.mountDashboardScaffolding)mountDashboardScaffolding(role,u);
}
function adminDash(d){const att=d.attendance.length?Math.round(d.attendance.filter(x=>x.status==='Present'||x.status==='Late').length/d.attendance.length*100):100;
return `<div class="page-head"><div><h1>Admin Dashboard</h1><p>University operations at a glance.</p></div><div class="actions"><a class="btn btn-primary" href="students.html">+ Add Student</a><a class="btn btn-secondary" href="reports.html">Reports</a></div></div>
<div class="grid grid-4">${[['🎓',d.students.length,'Total Students','students.html'],['👨‍🏫',d.teachers.length,'Total Teachers','teachers.html'],['🏛️',d.departments.length,'Departments','departments.html'],['📚',d.subjects.length,'Courses','subjects.html'],['🏫',d.classes.length,'Active Classes','classes.html'],['📝',d.assignments.length,'Assignments','assignments.html'],['🗓️',d.exams.filter(x=>x.status==='Scheduled').length,'Upcoming Exams','exams.html'],['💰',d.fees.reduce((a,x)=>a+Number(x.amount),0).toLocaleString(),'Fee Records','fees.html'],['📈',att+'%','Avg Attendance','attendance.html'],['✉️',d.messages.filter(x=>!x.read).length,'Unread Messages','messages.html']].map(x=>`<a class="card stat metric-accent" href="${x[3]}"><div class="stat-icon">${x[0]}</div><div><h3>${x[1]}</h3><p>${x[2]}</p><span class="trend">↗ Live data</span></div></a>`).join('')}</div>
<div class="grid grid-3" style="margin-top:16px"><div class="card"><div class="section-title"><h3>Student Enrollment</h3><span class="muted">Monthly</span></div>${chartBars([38,52,61,74,83,91],['Mar','Apr','May','Jun','Jul','Aug'])}</div>
<div class="card"><div class="section-title"><h3>Attendance Overview</h3></div><div class="donut"></div><p class="muted" style="text-align:center">Target ≥ 75%</p></div>
<div class="card"><div class="section-title"><h3>Fee Collection</h3></div>${chartBars([45,62,54,71,80,92],['Mar','Apr','May','Jun','Jul','Aug'])}</div></div>
<div class="grid grid-2" style="margin-top:16px"><div class="card"><div class="section-title"><h3>Recent Students</h3><a href="students.html" class="muted">View all</a></div>${d.students.slice(-5).reverse().map(s=>`<div class="list-item"><div><b>${esc(s.name)}</b><div class="muted">${esc(s.id)} · ${esc(s.program)}</div></div>${statusBadge(s.status)}</div>`).join('')}</div>
<div class="card"><div class="section-title"><h3>Upcoming Exams</h3><a href="exams.html" class="muted">View all</a></div>${d.exams.filter(x=>x.status==='Scheduled').slice(0,4).map(e=>`<div class="list-item"><div><b>${esc(e.name)}</b><div class="muted">${subjectName(e.subject)} · ${fmtDate(e.date)} · ${e.start}</div></div>${statusBadge(e.status)}</div>`).join('')}</div></div>
<div class="grid grid-2" style="margin-top:16px"><div class="card"><div class="section-title"><h3>Attendance Alerts</h3><a href="attendance.html">Open</a></div>${lowAttendance(d).map(x=>`<div class="list-item"><div><b>${esc(x.name)}</b><div class="muted">${x.pct}% attendance</div></div><span class="badge-status status-warning">Warning</span></div>`).join('')||'<div class="empty">No low-attendance alerts.</div>'}</div>
<div class="card"><div class="section-title"><h3>Announcements</h3><a href="announcements.html">Manage</a></div>${d.announcements.filter(x=>x.status==='Published').slice(-4).reverse().map(a=>`<div class="list-item"><div><b>${esc(a.title)}</b><div class="muted">${fmtDate(a.date)}</div></div>${statusBadge(a.priority)}</div>`).join('')}</div></div>`}
function chartBars(vals,labels){return `<div class="chart">${vals.map((v,i)=>`<div class="bar" style="height:${v*1.65}px"><b>${v}</b><small>${labels[i]}</small></div>`).join('')}</div>`}
function lowAttendance(d){return d.students.map(s=>{const x=attendanceStats(s.id);return {...s,pct:x.pct}}).filter(x=>x.pct<d.settings.attendanceWarning)}
function bindDashboardAdmin(){}
function teacherDash(d,u){const t=d.teachers.find(x=>x.id===u.teacherId);const subs=d.subjects.filter(s=>t?.subjects?.includes(s.id)||s.teacher===t?.id);const cls=d.classes.filter(c=>c.teacher===t?.id);const as=d.assignments.filter(a=>a.teacher===t?.id);return `<div class="page-head"><div><h1>Welcome, ${esc(u.name)}</h1><p>Teacher workspace · ${esc(t?.department||'Academic')}</p></div><div class="actions"><a class="btn btn-primary" href="attendance.html">Mark Attendance</a><a class="btn btn-secondary" href="assignments.html">Create Assignment</a></div></div>
<div class="grid grid-4"><div class="card stat"><div class="stat-icon">📚</div><div><h3>${subs.length}</h3><p>My Subjects</p></div></div><div class="card stat"><div class="stat-icon">👥</div><div><h3>${cls.reduce((a,c)=>a+c.students.length,0)}</h3><p>Students</p></div></div><div class="card stat"><div class="stat-icon">📝</div><div><h3>${as.length}</h3><p>Assignments</p></div></div><div class="card stat"><div class="stat-icon">🗓️</div><div><h3>${d.exams.filter(e=>subs.some(s=>s.id===e.subject)).length}</h3><p>Exams</p></div></div></div>
<div class="grid grid-2" style="margin-top:16px"><div class="card"><div class="section-title"><h3>My Subjects</h3><a href="subjects.html">View all</a></div>${subs.map(s=>`<div class="list-item"><div><b>${s.code} · ${esc(s.name)}</b><div class="muted">${esc(s.program)} · Semester ${s.semester}</div></div><span>${d.classes.filter(c=>c.subject===s.id).reduce((a,c)=>a+c.students.length,0)} students</span></div>`).join('')||'<div class="empty">No assigned subjects.</div>'}</div>
<div class="card"><div class="section-title"><h3>Today’s Classes</h3><a href="timetable.html">Timetable</a></div>${d.timetable.filter(x=>x.teacher===t?.id).map(x=>`<div class="list-item"><div><b>${x.start}–${x.end} · ${subjectName(x.subject)}</b><div class="muted">${x.room} · ${className(x.class)}</div></div></div>`).join('')||'<div class="empty">No classes scheduled.</div>'}</div></div>
<div class="card" style="margin-top:16px"><div class="section-title"><h3>Recent Assignment Activity</h3></div>${as.map(a=>{const subs=d.submissions.filter(s=>s.assignment===a.id);return `<div class="list-item"><div><b>${esc(a.title)}</b><div class="muted">${subs.length} submitted · ${subs.filter(s=>s.marks!==null).length} graded</div></div>${statusBadge(a.status)}</div>`}).join('')||'<div class="empty">No assignments.</div>'}</div>`}
function studentDash(d,u){const s=d.students.find(x=>x.id===u.studentId),g=studentGPA(s.id),att=attendanceStats(s.id),fees=feeTotal(s.id),as=d.assignments.map(a=>assignmentForStudent(a,s.id)).filter(a=>['Pending','Missing','Submitted','Late'].includes(a.studentStatus)), exams=d.exams.filter(e=>e.class&&d.classes.find(c=>c.id===e.class)?.students.includes(s.id)&&e.status==='Scheduled');return `<div class="page-head"><div><h1>Welcome, ${esc(s.name)}</h1><p>${esc(s.program)} · Semester ${s.semester} · Section ${s.section}</p></div></div>
<div class="grid grid-4"><div class="card stat"><div class="stat-icon">🎓</div><div><h3>${esc(s.id)}</h3><p>Student ID</p></div></div><div class="card stat"><div class="stat-icon">⭐</div><div><h3>${g.cgpa}</h3><p>CGPA</p></div></div><div class="card stat"><div class="stat-icon">📊</div><div><h3>${att.pct}%</h3><p>Attendance</p></div></div><div class="card stat"><div class="stat-icon">📝</div><div><h3>${as.length}</h3><p>Pending Work</p></div></div></div>
${att.pct<d.settings.attendanceWarning?`<div class="notice warning" style="margin-top:16px">⚠ Attendance is ${att.pct}%. Please maintain at least ${d.settings.attendanceWarning}% attendance.</div>`:''}
<div class="grid grid-2" style="margin-top:16px"><div class="card"><div class="section-title"><h3>Upcoming Assignments</h3><a href="assignments.html">View all</a></div>${as.slice(0,5).map(a=>`<div class="list-item"><div><b>${esc(a.title)}</b><div class="muted">${subjectName(a.subject)} · Due ${fmtDate(a.dueDate)}</div></div>${statusBadge(a.studentStatus)}</div>`).join('')||'<div class="empty">You are all caught up.</div>'}</div>
<div class="card"><div class="section-title"><h3>Upcoming Exams</h3><a href="exams.html">View all</a></div>${exams.slice(0,4).map(e=>`<div class="list-item"><div><b>${esc(e.name)}</b><div class="muted">${subjectName(e.subject)} · ${fmtDate(e.date)} · ${e.start}</div></div><span>${esc(e.room)}</span></div>`).join('')||'<div class="empty">No upcoming exams.</div>'}</div></div>
<div class="grid grid-2" style="margin-top:16px"><div class="card"><div class="section-title"><h3>Today’s Classes</h3><a href="timetable.html">Timetable</a></div>${d.timetable.filter(x=>{const c=d.classes.find(c=>c.id===x.class);return c?.students.includes(s.id)}).map(x=>`<div class="list-item"><div><b>${x.start}–${x.end} · ${subjectName(x.subject)}</b><div class="muted">${teacherName(x.teacher)} · ${x.room}</div></div></div>`).join('')||'<div class="empty">No timetable entries.</div>'}</div>
<div class="card"><div class="section-title"><h3>Fee Summary</h3><a href="fees.html">View fees</a></div><div class="kpi-row"><div class="kpi">Total <b>Rs. ${fees.total.toLocaleString()}</b></div><div class="kpi">Paid <b>Rs. ${fees.paid.toLocaleString()}</b></div><div class="kpi">Balance <b>Rs. ${(fees.total-fees.paid).toLocaleString()}</b></div></div></div></div>`}

