function renderGenericAdmin(schemaKey){const s=SCHEMAS[schemaKey],d=getData(s.key)||[],cfg=getData('settings')||{};let page=1,size=Math.max(3,Number(cfg.pageSize)||8);
 const root=document.getElementById('pageRoot');root.innerHTML=`<div class="page-head"><div><h1>${s.title}</h1><p>${s.desc}</p></div><div class="actions"><button class="btn btn-primary" id="addBtn">＋ Add ${s.title.replace(/s$/,'')}</button><button class="btn btn-light" id="exportBtn">Export CSV</button><button class="btn btn-light" id="printBtn">Print</button></div></div>
 <div class="card"><div class="filters" style="${cfg.searchEnabled===false&&cfg.filtersEnabled===false?'display:none':''}"><div class="filter-item" style="${cfg.searchEnabled===false?'display:none':''}"><input id="search" placeholder="Search ${s.title.toLowerCase()}…"></div><div class="filter-item" style="${cfg.filtersEnabled===false?'display:none':''}"><select id="statusFilter"><option value="">All statuses</option><option>Active</option><option>Inactive</option><option>Pending</option><option>Paid</option><option>Published</option></select></div><div class="filter-item"><select id="sort"><option value="default">Sort</option><option value="name">Name / Title</option><option value="id">ID</option></select></div></div><div class="table-wrap"><table class="table"><thead><tr>${s.columns.map(c=>`<th>${c[1]}</th>`).join('')}<th>Actions</th></tr></thead><tbody id="rows"></tbody></table></div><div id="pagination" class="pagination"></div></div>
 <div class="modal" id="recordModal"><div class="modal-box"><div class="modal-head"><h3 id="modalTitle">Add record</h3><button class="close" data-close-modal="recordModal">×</button></div><div class="modal-body"><form id="recordForm"><div class="form-grid">${s.fields.map(f=>fieldHTML(f)).join('')}</div><div class="form-actions"><button type="button" class="btn btn-light" data-close-modal="recordModal">Cancel</button><button class="btn btn-primary">Save changes</button></div></form></div></div></div>
 <div class="modal" id="confirmModal"><div class="modal-box" style="max-width:430px"><div class="modal-head"><h3>Confirm deletion</h3><button class="close" data-close-modal="confirmModal">×</button></div><div class="modal-body"><div class="notice danger">⚠ This action cannot be undone.</div><p id="confirmMessage">Are you sure?</p><div class="form-actions"><button class="btn btn-light" data-close-modal="confirmModal">Cancel</button><button class="btn btn-danger" id="confirmYes">Delete</button></div></div></div></div>`;
 setupGlobal();
 const form=document.getElementById('recordForm');
 function draw(){let q=cfg.searchEnabled===false?'':document.getElementById('search').value.toLowerCase(),st=cfg.filtersEnabled===false?'':document.getElementById('statusFilter').value,sort=document.getElementById('sort').value;let rows=getData(s.key).filter(x=>(!q||JSON.stringify(x).toLowerCase().includes(q))&&(!st||x.status===st));if(sort!=='default')rows.sort((a,b)=>String(a[sort]||a.name||'').localeCompare(String(b[sort]||b.name||'')));const pg=paginate(rows,page,size);document.getElementById('rows').innerHTML=pg.items.length?pg.items.map(r=>`<tr>${s.columns.map(c=>`<td>${c[0]==='status'?statusBadge(r[c[0]]):c[0].includes('Date')?fmtDate(r[c[0]]):c[0]==='teacher'?esc(teacherName(r[c[0]])):c[0]==='subject'?esc(subjectName(r[c[0]])):c[0]==='student'?esc(studentName(r[c[0]])):c[0]==='class'?esc(className(r[c[0]])):esc(r[c[0]]??'—')}</td>`).join('')}<td><div class="actions"><button class="btn btn-light btn-sm" data-edit="${r.id}">Edit</button><button class="btn btn-danger btn-sm" data-del="${r.id}">Delete</button></div></td></tr>`).join(''):`<tr><td colspan="${s.columns.length+1}"><div class="empty">No matching records.</div></td></tr>`;renderPagination(document.getElementById('pagination'),pg.pages,page,x=>{page=x;draw()});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(s.key,b.dataset.edit));document.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>confirmAction('Are you sure you want to delete this record?',()=>{deleteRecord(s.key,b.dataset.del);unlinkAccount(s.key,b.dataset.del);toast(`${s.title.slice(0,-1)} deleted successfully.`);draw()}))}
 document.getElementById('search').oninput=()=>{page=1;draw()};document.getElementById('statusFilter').onchange=()=>{page=1;draw()};document.getElementById('sort').onchange=draw;
 document.getElementById('addBtn').onclick=()=>edit(s.key,null);document.getElementById('exportBtn').onclick=()=>csvDownload(s.key+'.csv',[s.columns.map(c=>c[1]),...getData(s.key).map(r=>s.columns.map(c=>r[c[0]]))]);document.getElementById('printBtn').onclick=()=>printSection(s.title,document.querySelector('.table-wrap').innerHTML);
 function edit(key,id){const rec=id?findRecord(key,id):{};document.getElementById('modalTitle').textContent=id?'Edit record':`Add ${s.title.replace(/s$/,'')}`;form.dataset.id=id||'';s.fields.forEach(f=>{const el=form.elements[f[0]];if(el)el.value=Array.isArray(rec[f[0]])?rec[f[0]].join(', '):(rec[f[0]]??'')});populateDynamic(form);openModal('recordModal')}
 form.onsubmit=e=>{e.preventDefault();const raw=formData(form);try{if(!raw.id)throw Error('ID is required.');if(s.key==='students'&&getData('students').some(x=>x.id===raw.id&&x.id!==form.dataset.id))throw Error('Student ID must be unique.');if(s.key==='teachers'&&getData('teachers').some(x=>x.id===raw.id&&x.id!==form.dataset.id))throw Error('Teacher ID must be unique.');if(s.key==='subjects'&&getData('subjects').some(x=>x.code===raw.code&&x.id!==form.dataset.id))throw Error('Subject code must be unique.');
if(s.key==='classes'){raw.students=String(raw.students||'').split(',').map(x=>x.trim()).filter(Boolean);if(raw.students.some(id=>!findRecord('students',id)))throw Error('Every Student ID in the roster must exist.');}
const id=form.dataset.id;
if(id){updateRecord(s.key,id,raw);syncLinkedAccount(s.key,id,raw);}else {const created=addRecord(s.key,raw);if(s.key==='students'){addRecord('users',{id:generateId('USR'),role:'student',email:created.email,password:created.password||'student123',name:created.name,status:created.status||'Active',studentId:created.id,department:created.department,program:created.program,semester:Number(created.semester||1),section:created.section||''});}if(s.key==='teachers'){addRecord('users',{id:generateId('USR'),role:'teacher',email:created.email,password:created.password||'teacher123',name:created.name,status:created.status||'Active',teacherId:created.id,department:created.department});}}
closeModal('recordModal');toast(`${s.title.slice(0,-1)} ${id?'updated':'added'} successfully.`);draw()}catch(err){toast(err.message,'error')}}
 draw();
}
function fieldHTML(f){let [name,label,type,extra]=f;if(type.startsWith('select')){let opts=type==='select'?extra.split('|').map(x=>`<option>${x}</option>`).join(''):'';return `<div class="form-group"><label>${label}${extra===true?' *':''}</label><select class="form-control" name="${name}" id="${name}">${opts}</select></div>`}if(type==='textarea')return `<div class="form-group full"><label>${label}</label><textarea class="form-control" name="${name}" id="${name}" rows="3"></textarea></div>`;return `<div class="form-group"><label>${label}${extra===true?' *':''}</label><input class="form-control" type="${type}" name="${name}" id="${name}" ${extra===true?'required':''}></div>`}
function populateDynamic(form){const d=db();[['department',d.departments,x=>x.name,x=>x.name],['program',d.programs,x=>x.name,x=>x.name],['teacher',d.teachers,x=>x.name,x=>x.id],['subject',d.subjects,x=>`${x.code} — ${x.name}`,x=>x.id],['class',d.classes,x=>x.name,x=>x.id],['student',d.students,x=>`${x.id} — ${x.name}`,x=>x.id]].forEach(([id,items,l,v])=>{const el=form.elements[id];if(el&&el.tagName==='SELECT'&&el.options.length<=1)populateSelect(id,items,l,v,'Select…')})}
function renderStudents(){renderGenericAdmin('students')}
function renderTeachers(){renderGenericAdmin('teachers')}
function renderDepartments(){renderGenericAdmin('departments')}
function renderPrograms(){renderGenericAdmin('programs')}
function renderSubjects(){renderGenericAdmin('subjects')}
function renderClasses(){renderGenericAdmin('classes')}
function renderExams(){renderGenericAdmin('exams')}
function renderFees(){renderGenericAdmin('fees')}

function renderTimetable(role,u){
 const d=db();let rows=d.timetable;if(role==='teacher')rows=rows.filter(x=>x.teacher===u.teacherId);if(role==='student'){const st=d.students.find(x=>x.id===u.studentId);rows=rows.filter(x=>d.classes.find(c=>c.id===x.class)?.students.includes(st?.id))}
 const days=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];const settings=d.settings||{},viewSaved=localStorage.getItem('eadTimetableView');let view=viewSaved||(settings.defaultView||'board');const pageSize=Math.max(3,Number(settings.pageSize)||8),state={page:1};
 const filtered=()=>{const q=settings.searchEnabled===false?'':(document.getElementById('ttSearch')?.value||'').trim().toLowerCase(),day=settings.filtersEnabled===false?'':document.getElementById('ttDay')?.value||'',teacher=settings.filtersEnabled===false?'':document.getElementById('ttTeacherFilter')?.value||'',room=settings.filtersEnabled===false?'':(document.getElementById('ttRoom')?.value||'').trim().toLowerCase();return rows.filter(x=>{const hay=`${x.day} ${x.start} ${x.end} ${subjectName(x.subject)} ${teacherName(x.teacher)} ${className(x.class)} ${x.room}`.toLowerCase();return(!q||hay.includes(q))&&(!day||x.day===day)&&(!teacher||x.teacher===teacher)&&(!room||String(x.room).toLowerCase().includes(room))})};
 const actions=x=>role==='admin'?`<div class="event-actions"><button class="btn btn-light btn-sm" data-ttedit="${x.id}">Edit</button><button class="btn btn-danger btn-sm" data-ttdel="${x.id}">Delete</button></div>`:'';
 const tableView=items=>`<div class="table-wrap timetable-table"><table class="table"><thead><tr><th>Day</th><th>Time</th><th>Subject</th><th>Teacher</th><th>Class</th><th>Room</th>${role==='admin'?'<th>Actions</th>':''}</tr></thead><tbody>${items.map(x=>`<tr><td><b>${x.day}</b></td><td>${x.start}–${x.end}</td><td>${esc(subjectName(x.subject))}</td><td>${esc(teacherName(x.teacher))}</td><td>${esc(className(x.class))}</td><td>${esc(x.room)}</td>${role==='admin'?`<td><div class="actions"><button class="btn btn-light btn-sm" data-ttedit="${x.id}">Edit</button><button class="btn btn-danger btn-sm" data-ttdel="${x.id}">Delete</button></div></td>`:''}</tr>`).join('')||`<tr><td colspan="${role==='admin'?7:6}"><div class="empty">No timetable entries match your filters.</div></td></tr>`}</tbody></table></div>`;
 const boardView=items=>`<div class="calendar-grid">${days.map(day=>`<div class="day-col"><h4>${day}</h4>${items.filter(x=>x.day===day).sort((a,b)=>a.start.localeCompare(b.start)).map(x=>`<div class="event"><strong>${x.start}–${x.end}</strong><div>${esc(subjectName(x.subject))}</div><div class="event-meta">${esc(teacherName(x.teacher))} · ${esc(x.room)}<br>${esc(className(x.class))}</div>${actions(x)}</div>`).join('')||'<span class="muted">No classes</span>'}</div>`).join('')}</div>`;
 const root=document.getElementById('pageRoot');root.innerHTML=`<div class="page-head"><div><h1>Timetable</h1><p>Search, filter and switch between board and table views. Export creates a print-ready official timetable.</p></div><div class="timetable-toolbar"><div class="view-toggle"><button type="button" id="ttBoard" class="${view==='board'?'active':''}">▦ Board</button><button type="button" id="ttTable" class="${view==='table'?'active':''}">☷ Table</button></div><button class="btn btn-light" id="exportTT">Export Timetable</button>${role==='admin'?'<button class="btn btn-primary" id="addTT">＋ Add Entry</button>':''}</div></div><div class="card"><div class="filters" style="${settings.searchEnabled===false&&settings.filtersEnabled===false?'display:none':''}"><div class="filter-item" style="${settings.searchEnabled===false?'display:none':''}"><input id="ttSearch" class="form-control" placeholder="Search subject, teacher, class, room…"></div><div class="filter-item" style="${settings.filtersEnabled===false?'display:none':''}"><select id="ttDay" class="form-control"><option value="">All days</option>${days.map(x=>`<option>${x}</option>`).join('')}</select></div><div class="filter-item" style="${settings.filtersEnabled===false?'display:none':''}"><select id="ttTeacherFilter" class="form-control"><option value="">All teachers</option>${d.teachers.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div class="filter-item" style="${settings.filtersEnabled===false?'display:none':''}"><input id="ttRoom" class="form-control" placeholder="Room"></div></div><div class="section-title"><h3>Weekly Schedule</h3><span class="muted" id="ttCount"></span></div><div id="ttView"></div><div id="ttPagination" class="pagination"></div></div>${role==='admin'?`<div class="modal" id="ttModal"><div class="modal-box"><div class="modal-head"><h3 id="ttModalTitle">Add Timetable Entry</h3><button class="close" data-close-modal="ttModal">×</button></div><div class="modal-body"><form id="ttForm"><input type="hidden" name="id"><div class="form-grid"><div class="form-group"><label>Day</label><select name="day" class="form-control">${days.map(x=>`<option>${x}</option>`).join('')}</select></div><div class="form-group"><label>Start</label><input name="start" type="time" class="form-control" required></div><div class="form-group"><label>End</label><input name="end" type="time" class="form-control" required></div><div class="form-group"><label>Subject</label><select name="subject" id="ttSubject" class="form-control" required></select></div><div class="form-group"><label>Teacher</label><select name="teacher" id="ttTeacher" class="form-control" required></select></div><div class="form-group"><label>Room</label><input name="room" class="form-control" required></div><div class="form-group"><label>Class</label><select name="class" id="ttClass" class="form-control" required></select></div></div><div class="form-actions"><button type="button" class="btn btn-light" data-close-modal="ttModal">Cancel</button><button class="btn btn-primary">Save Entry</button></div></form></div></div></div>`:''}`;setupGlobal();
 const draw=()=>{const all=filtered(),pages=Math.max(1,Math.ceil(all.length/pageSize));if(state.page>pages)state.page=pages;const items=all.slice((state.page-1)*pageSize,state.page*pageSize);document.getElementById('ttCount').textContent=`${all.length} matching entr${all.length===1?'y':'ies'}`;document.getElementById('ttView').innerHTML=view==='table'?tableView(items):boardView(items);renderPagination(document.getElementById('ttPagination'),pages,state.page,x=>{state.page=x;draw()});bindTTButtons()};
 const reset=()=>{state.page=1;draw()};['ttSearch','ttRoom'].forEach(id=>document.getElementById(id).oninput=reset);['ttDay','ttTeacherFilter'].forEach(id=>document.getElementById(id).onchange=reset);
 const switchView=v=>{view=v;localStorage.setItem('eadTimetableView',v);state.page=1;draw();document.getElementById('ttBoard').classList.toggle('active',v==='board');document.getElementById('ttTable').classList.toggle('active',v==='table')};document.getElementById('ttBoard').onclick=()=>switchView('board');document.getElementById('ttTable').onclick=()=>switchView('table');
 document.getElementById('exportTT').onclick=()=>{const all=filtered().sort((a,b)=>days.indexOf(a.day)-days.indexOf(b.day)||a.start.localeCompare(b.start));const html=`<div class="table-wrap"><table class="table"><thead><tr><th>Day</th><th>Time</th><th>Subject</th><th>Teacher</th><th>Class</th><th>Room</th></tr></thead><tbody>${all.map(x=>`<tr><td>${esc(x.day)}</td><td>${esc(x.start)}–${esc(x.end)}</td><td>${esc(subjectName(x.subject))}</td><td>${esc(teacherName(x.teacher))}</td><td>${esc(className(x.class))}</td><td>${esc(x.room)}</td></tr>`).join('')||'<tr><td colspan="6">No timetable entries match the current filters.</td></tr>'}</tbody></table></div>`;printSection(`${settings.university||'EAD UNIVERSITY'} — Official Timetable`,html)};
 function bindTTButtons(){document.querySelectorAll('[data-ttedit]').forEach(b=>b.onclick=()=>openEdit(b.dataset.ttedit));document.querySelectorAll('[data-ttdel]').forEach(b=>b.onclick=()=>confirmAction('Delete this timetable entry?',()=>{deleteRecord('timetable',b.dataset.ttdel);toast('Timetable entry deleted.');renderTimetable(role,u)}))}
 let openEdit=()=>{};if(role==='admin'){populateSelect('ttSubject',d.subjects,x=>`${x.code} — ${x.name}`,x=>x.id);populateSelect('ttTeacher',d.teachers,x=>x.name,x=>x.id);populateSelect('ttClass',d.classes,x=>x.name,x=>x.id);const form=document.getElementById('ttForm'),title=document.getElementById('ttModalTitle');openEdit=id=>{form.reset();form.elements.id.value='';title.textContent='Add Timetable Entry';if(id){const old=findRecord('timetable',id);if(!old)return;title.textContent='Edit Timetable Entry';Object.entries(old).forEach(([k,v])=>{if(form.elements[k])form.elements[k].value=v});form.elements.id.value=id}openModal('ttModal')};document.getElementById('addTT').onclick=()=>openEdit(null);form.onsubmit=e=>{e.preventDefault();const r=formData(form),id=r.id;delete r.id;if(r.end<=r.start)return toast('End time must be after start time.','error');const conflict=db().timetable.some(x=>x.id!==id&&x.day===r.day&&x.start<r.end&&r.start<x.end&&(x.teacher===r.teacher||x.room.toLowerCase()===r.room.toLowerCase()||x.class===r.class));if(conflict)return toast('Conflict detected: teacher, room, or class is already booked.','error');if(id)updateRecord('timetable',id,r);else addRecord('timetable',r);toast(id?'Timetable entry updated successfully.':'Timetable entry added successfully.');closeModal('ttModal');renderTimetable(role,u)}}draw();
}
function renderAttendance(role,u){const d=db();let students=d.students,subjects=d.subjects;if(role==='teacher'){const t=u.teacherId;subjects=subjects.filter(s=>s.teacher===t);students=[]}if(role==='student'){const s=d.students.find(x=>x.id===u.studentId);students=[s];subjects=subjects.filter(sub=>d.classes.some(c=>c.subject===sub.id&&c.students.includes(s.id)))}
document.getElementById('pageRoot').innerHTML=`<div class="page-head"><div><h1>Attendance</h1><p>${role==='teacher'?'Mark and review attendance for assigned classes.':'Attendance summary and alerts.'}</p></div></div>
${role==='teacher'?`<div class="card"><div class="form-grid"><div class="form-group"><label>Subject</label><select id="attSubject" class="form-control"></select></div><div class="form-group"><label>Class</label><select id="attClass" class="form-control"></select></div><div class="form-group"><label>Date</label><input id="attDate" type="date" value="${todayISO()}" class="form-control"></div><div class="form-group"><label>Lecture Time</label><input id="attTime" type="time" class="form-control" value="09:00"></div></div><div id="attRoster" style="margin-top:15px"></div></div>`:
`<div class="grid grid-3">${subjects.map(s=>{const a=attendanceStats(students[0]?.id,s.id);return `<div class="card"><div class="section-title"><h3>${esc(s.name)}</h3>${statusBadge(a.pct<d.settings.attendanceWarning?'Warning':'Good')}</div><div style="font-size:30px;font-weight:800;color:var(--brown-dark)">${a.pct}%</div><div class="progress"><span style="width:${a.pct}%"></span></div><div class="kpi-row" style="margin-top:10px"><div class="kpi">Present <b>${a.present}</b></div><div class="kpi">Absent <b>${a.absent}</b></div><div class="kpi">Late <b>${a.late}</b></div></div></div>`}).join('')}</div>
<div class="card" style="margin-top:16px"><div class="section-title"><h3>Attendance History</h3><button class="btn btn-light btn-sm" id="attExport">Export CSV</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Student</th><th>Subject</th><th>Date</th><th>Status</th><th>Notes</th></tr></thead><tbody>${d.attendance.filter(a=>role==='student'?a.student===students[0]?.id:true).slice().reverse().map(a=>`<tr><td>${esc(studentName(a.student))}</td><td>${esc(subjectName(a.subject))}</td><td>${fmtDate(a.date)}</td><td>${statusBadge(a.status)}</td><td>${esc(a.notes)}</td></tr>`).join('')}</tbody></table></div></div>`}`;
if(role==='teacher'){const t=u.teacherId;populateSelect('attSubject',subjects,x=>`${x.code} — ${x.name}`,x=>x.id);function load(){const sid=document.getElementById('attSubject').value;const cls=d.classes.filter(c=>c.teacher===t&&c.subject===sid);populateSelect('attClass',cls,x=>x.name,x=>x.id);document.getElementById('attClass').onchange=draw}document.getElementById('attSubject').onchange=load;function draw(){const cid=document.getElementById('attClass').value;if(!cid)return;const c=d.classes.find(x=>x.id===cid),date=document.getElementById('attDate').value;document.getElementById('attRoster').innerHTML=`<div class="actions" style="margin-bottom:10px"><button class="btn btn-light btn-sm" id="allPresent">Mark all present</button><button class="btn btn-light btn-sm" id="allAbsent">Mark all absent</button><button class="btn btn-primary btn-sm" id="saveAtt">Save attendance</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Student</th><th>ID</th><th>Status</th><th>Notes</th></tr></thead><tbody>${c.students.map(sid=>{const st=findRecord('students',sid);const old=d.attendance.find(a=>a.student===sid&&a.subject===c.subject&&a.date===date);return `<tr><td>${esc(st.name)}</td><td>${sid}</td><td><select class="form-control att-status" data-student="${sid}"><option ${old?.status==='Present'?'selected':''}>Present</option><option ${old?.status==='Absent'?'selected':''}>Absent</option><option ${old?.status==='Late'?'selected':''}>Late</option><option ${old?.status==='Excused'?'selected':''}>Excused</option></select></td><td><input class="form-control att-note" data-student="${sid}" value="${esc(old?.notes||'')}"></td></tr>`}).join('')}</tbody></table></div>`;document.getElementById('allPresent').onclick=()=>document.querySelectorAll('.att-status').forEach(x=>x.value='Present');document.getElementById('allAbsent').onclick=()=>document.querySelectorAll('.att-status').forEach(x=>x.value='Absent');document.getElementById('saveAtt').onclick=()=>{const rows=[...document.querySelectorAll('.att-status')].map(el=>({student:el.dataset.student,subject:c.subject,class:cid,teacher:t,date,status:el.value,notes:document.querySelector(`.att-note[data-student="${el.dataset.student}"]`).value}));saveAttendance(rows);draw()}}load()}}

function submissionModal(d){
 return `<div class="modal" id="submissionModal"><div class="modal-box"><div class="modal-head"><h3>Submit Assignment</h3><button class="close" data-close-modal="submissionModal">×</button></div><div class="modal-body"><form id="submissionForm"><input type="hidden" name="assignment" id="submissionAssignment"><div class="form-group"><label>Submission text</label><textarea name="text" class="form-control" rows="5" placeholder="Add a short note or answer..."></textarea></div><div class="form-group"><label>File name (demo attachment)</label><input name="fileName" class="form-control" placeholder="e.g. project.zip"></div><div class="form-group"><label>Submission link (optional)</label><input name="link" type="url" class="form-control" placeholder="https://..."></div><div class="form-actions"><button type="button" class="btn btn-light" data-close-modal="submissionModal">Cancel</button><button class="btn btn-primary" type="submit">Submit Assignment</button></div></form></div></div></div>`;
}

function saveStudentSubmission(form,u){
 const d=db(),aid=form.elements.assignment?.value,a=findRecord('assignments',aid);
 if(!a)throw Error('Assignment not found.');
 if(!u?.studentId)throw Error('Student account is not linked to a student record.');
 const now=new Date(),due=new Date(`${a.dueDate}T${a.dueTime||'23:59'}`),existing=d.submissions.find(s=>s.assignment===aid&&s.student===u.studentId);
 const late=now>due;
 if(late && a.lateAllowed===false && !existing)throw Error('The submission deadline has passed.');
 const payload={assignment:aid,student:u.studentId,date:now.toISOString(),status:late?'Late':'Submitted',fileName:String(form.elements.fileName?.value||'').trim(),text:String(form.elements.text?.value||'').trim(),link:String(form.elements.link?.value||'').trim(),marks:existing?.marks??null,feedback:existing?.feedback||'',reviewed:existing?.reviewed||false};
 if(!payload.text&&!payload.fileName&&!payload.link)throw Error('Add submission text, a file name, or a submission link.');
 if(existing)updateRecord('submissions',existing.id,payload);else addRecord('submissions',payload);
 return payload;
}

function renderAssignments(role,u){
 const d=db(),manage=role==='teacher'||role==='admin';let as=d.assignments;
 if(role==='teacher')as=as.filter(a=>a.teacher===u.teacherId);
 if(role==='student'){const st=d.students.find(x=>x.id===u.studentId);as=as.filter(a=>d.classes.find(c=>c.id===a.class)?.students.includes(st?.id)).map(a=>assignmentForStudent(a,st.id))}
 const cfg=d.settings||{},pageSize=Math.max(3,Number(cfg.pageSize)||6),state={page:1};
 document.getElementById('pageRoot').innerHTML=`<div class="page-head"><div><h1>Assignments</h1><p>${role==='student'?'Track pending, submitted and graded work.':'Create, publish and grade assignments.'}</p></div>${manage?'<button class="btn btn-primary" id="createAssignment">＋ Create Assignment</button>':''}</div><div class="grid grid-3">${role==='student'?[['⏳',as.filter(a=>a.studentStatus==='Pending').length,'Pending'],['📤',as.filter(a=>['Submitted','Late'].includes(a.studentStatus)).length,'Submitted'],['🏆',as.filter(a=>a.studentStatus==='Graded').length,'Graded']].map(x=>`<div class="card stat"><div class="stat-icon">${x[0]}</div><div><h3>${x[1]}</h3><p>${x[2]}</p></div></div>`).join(''):['Total Assignments','Published','Submissions'].map((x,i)=>`<div class="card stat"><div class="stat-icon">${['📝','📣','📤'][i]}</div><div><h3>${i===0?as.length:i===1?as.filter(a=>a.status==='Published').length:d.submissions.filter(s=>as.some(a=>a.id===s.assignment)).length}</h3><p>${x}</p></div></div>`).join('')}</div><div class="card" style="margin-top:16px"><div class="filters" style="${cfg.searchEnabled===false&&cfg.filtersEnabled===false?'display:none':''}"><div class="filter-item" style="${cfg.searchEnabled===false?'display:none':''}"><input id="asSearch" class="form-control" placeholder="Search assignments, subjects, teachers…"></div><div class="filter-item" style="${cfg.filtersEnabled===false?'display:none':''}"><select id="asStatus" class="form-control"><option value="">All statuses</option>${role==='student'?'<option>Pending</option><option>Submitted</option><option>Late</option><option>Graded</option>':'<option>Published</option><option>Draft</option>'}</select></div></div><div class="grid grid-2" id="assignmentList"></div><div id="assignmentPagination" class="pagination"></div></div>${manage?assignmentModal(d,role,u):''}${role==='student'?submissionModal(d):''}`;setupGlobal();
 const draw=()=>{const q=cfg.searchEnabled===false?'':document.getElementById('asSearch').value.trim().toLowerCase(),st=cfg.filtersEnabled===false?'':document.getElementById('asStatus').value,filtered=as.filter(a=>{const hay=`${a.title} ${a.description} ${subjectName(a.subject)} ${teacherName(a.teacher)} ${a.dueDate}`.toLowerCase();return(!q||hay.includes(q))&&(!st||(role==='student'?a.studentStatus===st:a.status===st))}),pages=Math.max(1,Math.ceil(filtered.length/pageSize));if(state.page>pages)state.page=pages;const items=filtered.slice((state.page-1)*pageSize,state.page*pageSize);document.getElementById('assignmentList').innerHTML=items.map(a=>{const sub=a.submission||d.submissions.find(s=>s.assignment===a.id&&s.student===u.studentId);return `<div class="card course-card"><div class="section-title"><span class="course-code">${esc(subjectName(a.subject))}</span>${statusBadge(role==='student'?a.studentStatus:a.status)}</div><h3>${esc(a.title)}</h3><p>${esc(a.description)}</p><div class="kpi-row"><div class="kpi">Due <b>${fmtDate(a.dueDate)}</b></div><div class="kpi">Marks <b>${a.marks}</b></div><div class="kpi">Teacher <b>${esc(teacherName(a.teacher))}</b></div></div>${role==='student'?`<div class="actions" style="margin-top:10px">${['Pending','Late'].includes(a.studentStatus)?`<button class="btn btn-primary btn-sm" data-submit="${a.id}">Submit Now</button>`:''}${sub?`<button class="btn btn-light btn-sm" data-view-own="${a.id}">View Submission</button>`:''}</div>`:`<div class="actions" style="margin-top:12px"><button class="btn btn-light btn-sm" data-view-sub="${a.id}">View Submissions</button><button class="btn btn-secondary btn-sm" data-edit-ass="${a.id}">Edit</button><button class="btn btn-danger btn-sm" data-del-ass="${a.id}">Delete</button></div>`}</div>`}).join('')||'<div class="card empty" style="grid-column:1/-1">No assignments found.</div>';renderPagination(document.getElementById('assignmentPagination'),pages,state.page,x=>{state.page=x;draw()});bindButtons()};
 document.getElementById('asSearch').oninput=()=>{state.page=1;draw()};document.getElementById('asStatus').onchange=()=>{state.page=1;draw()};
 if(manage)document.getElementById('createAssignment').onclick=()=>{const f=document.getElementById('assignmentForm');f?.reset();delete f?.dataset.editId;document.querySelector('#assignmentModal h3').textContent='Create Assignment';openModal('assignmentModal');populateAssignmentSelects(role,u)};
 function bindButtons(){if(manage){document.querySelectorAll('[data-del-ass]').forEach(b=>b.onclick=()=>confirmAction('Delete this assignment and its submissions?',()=>{deleteRecord('assignments',b.dataset.delAss);getData('submissions').filter(s=>s.assignment===b.dataset.delAss).forEach(s=>deleteRecord('submissions',s.id));toast('Assignment deleted successfully.');renderAssignments(role,u)}));document.querySelectorAll('[data-view-sub]').forEach(b=>b.onclick=()=>showSubmissions(b.dataset.viewSub,u));document.querySelectorAll('[data-edit-ass]').forEach(b=>b.onclick=()=>editAssignment(b.dataset.editAss,u,role))}else{document.querySelectorAll('[data-submit]').forEach(b=>b.onclick=()=>{const f=document.getElementById('submissionForm');if(f){f.reset();f.elements.assignment.value=b.dataset.submit}openModal('submissionModal')});document.querySelectorAll('[data-view-own]').forEach(b=>b.onclick=()=>showOwnSubmission(b.dataset.viewOwn,u));const submissionForm=document.getElementById('submissionForm');if(submissionForm)submissionForm.onsubmit=e=>{e.preventDefault();try{saveStudentSubmission(e.target,u);toast('Assignment submitted successfully.');closeModal('submissionModal');renderAssignments(role,u)}catch(err){toast(err.message,'error')}}}}
 draw();
}
function populateAssignmentSelects(role,u,selected={}){const d=db();const teachers=role==='teacher'?d.teachers.filter(x=>x.id===u.teacherId):d.teachers;populateSelect('asTeacher',teachers,x=>x.name,x=>x.id,'Select teacher…');populateSelect('asSubject',role==='teacher'?d.subjects.filter(x=>x.teacher===u.teacherId):d.subjects,x=>`${x.code} — ${x.name}`,x=>x.id,'Select subject…');populateSelect('asClass',role==='teacher'?d.classes.filter(x=>x.teacher===u.teacherId):d.classes,x=>x.name,x=>x.id,'Select class…');if(selected.teacher&&document.getElementById('asTeacher'))document.getElementById('asTeacher').value=selected.teacher;if(selected.subject)document.getElementById('asSubject').value=selected.subject;if(selected.class)document.getElementById('asClass').value=selected.class}
function editAssignment(id,u,role){const a=findRecord('assignments',id),f=document.getElementById('assignmentForm');if(!a||!f)return;f.dataset.editId=id;['subject','class','title','dueDate','dueTime','marks','submissionType','lateAllowed','description','instructions'].forEach(k=>{if(f.elements[k])f.elements[k].value=a[k]??''});document.querySelector('#assignmentModal h3').textContent='Edit Assignment';populateAssignmentSelects(role,u,{teacher:a.teacher,subject:a.subject,class:a.class});openModal('assignmentModal')}
function assignmentModal(d,role,u){return `<div class="modal" id="assignmentModal"><div class="modal-box"><div class="modal-head"><h3>Create Assignment</h3><button class="close" data-close-modal="assignmentModal">×</button></div><div class="modal-body"><form id="assignmentForm"><div class="form-grid">${role==='admin'?'<div class="form-group"><label>Teacher</label><select id="asTeacher" name="teacher" class="form-control" required></select></div>':''}<div class="form-group"><label>Subject</label><select id="asSubject" name="subject" class="form-control" required></select></div><div class="form-group"><label>Class</label><select id="asClass" name="class" class="form-control" required></select></div><div class="form-group"><label>Title</label><input name="title" class="form-control" required></div><div class="form-group"><label>Due Date</label><input name="dueDate" type="date" min="${todayISO()}" class="form-control" required></div><div class="form-group"><label>Due Time</label><input name="dueTime" type="time" value="23:59" class="form-control" required></div><div class="form-group"><label>Total Marks</label><input name="marks" type="number" min="1" class="form-control" required></div><div class="form-group"><label>Submission Type</label><select name="submissionType" class="form-control"><option>File upload</option><option>Text response</option><option>Link submission</option><option>File and text</option></select></div><div class="form-group"><label>Late Submission</label><select name="lateAllowed" class="form-control"><option value="true" ${d.settings?.lateSubmission!==false?'selected':''}>Allowed</option><option value="false" ${d.settings?.lateSubmission===false?'selected':''}>Not allowed</option></select></div><div class="form-group full"><label>Description</label><textarea name="description" class="form-control" rows="3" required></textarea></div><div class="form-group full"><label>Instructions</label><textarea name="instructions" class="form-control" rows="3"></textarea></div></div><div class="form-actions"><button type="button" class="btn btn-light" data-close-modal="assignmentModal">Cancel</button><button class="btn btn-primary">Publish Assignment</button></div></form></div></div></div>`}
function showSubmissions(aid,u){
 const a=findRecord('assignments',aid); if(!a)return;
 const d=db(), submissions=d.submissions.filter(s=>s.assignment===aid);
 const modal=document.createElement('div'); modal.className='modal show'; modal.id='submissionsModal';
 modal.innerHTML=`<div class="modal-box" style="max-width:900px"><div class="modal-head"><h3>${esc(a.title)} — Submissions (${submissions.length})</h3><button class="close" data-close-modal="submissionsModal">×</button></div><div class="modal-body">
 ${submissions.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Student</th><th>Submitted</th><th>Status</th><th>File</th><th>Marks</th><th>Feedback</th><th>Action</th></tr></thead><tbody>${submissions.map(s=>`<tr><td>${esc(studentName(s.student))}</td><td>${fmtDateTime(s.date)}</td><td>${statusBadge(s.status)}</td><td>${esc(s.fileName||'—')}</td><td>${s.marks??'—'} / ${a.marks}</td><td>${esc(s.feedback||'—')}</td><td><button type="button" class="btn btn-primary btn-sm" data-grade-sub="${s.id}">${s.status==='Graded'?'Update Grade':'Grade'}</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No submissions have been received for this assignment yet.</div>'}
 <div class="form-actions"><button type="button" class="btn btn-light" data-close-modal="submissionsModal">Close</button></div></div></div>`;
 document.getElementById('pageRoot').appendChild(modal); setupGlobal();
 modal.querySelectorAll('[data-grade-sub]').forEach(btn=>btn.onclick=()=>{
   const sub=findRecord('submissions',btn.dataset.gradeSub); if(!sub)return;
   const marks=window.prompt(`Enter marks (0–${a.marks})`,sub.marks??''); if(marks===null)return;
   const n=Number(marks); if(!Number.isFinite(n)||n<0||n>Number(a.marks))return toast(`Marks must be between 0 and ${a.marks}.`,'error');
   const feedbackInput=window.prompt('Feedback (optional)',sub.feedback||'');
   const feedback=feedbackInput===null?(sub.feedback||''):feedbackInput;
   try{gradeSubmission(sub.id,n,feedback,true); modal.remove(); showSubmissions(aid,u);}catch(e){toast(e.message,'error')}
 });
}
function showOwnSubmission(aid,u){const a=findRecord('assignments',aid),s=getData('submissions').find(x=>x.assignment===aid&&x.student===u.studentId);if(!a||!s)return;const root=document.getElementById('pageRoot');root.insertAdjacentHTML('beforeend',`<div class="modal show" id="ownSubmissionModal"><div class="modal-box"><div class="modal-head"><h3>${esc(a.title)} — My Submission</h3><button class="close" data-close-modal="ownSubmissionModal">×</button></div><div class="modal-body"><p><b>Status:</b> ${statusBadge(s.status)}</p><p><b>Submitted:</b> ${fmtDateTime(s.date)}</p><p><b>File:</b> ${esc(s.fileName||'None')}</p><p><b>Response:</b><br>${esc(s.text||'No text response.')}</p><p><b>Link:</b> ${s.link?`<a href="${esc(s.link)}" target="_blank" rel="noopener">Open submission link</a>`:'None'}</p><p><b>Marks:</b> ${s.marks??'Not graded'} / ${a.marks}</p><p><b>Feedback:</b> ${esc(s.feedback||'No feedback yet.')}</p></div></div></div>`);setupGlobal()}
function renderMessages(role,u){const d=db(),inbox=d.messages.filter(m=>m.to===u.id),sent=d.messages.filter(m=>m.from===u.id);document.getElementById('pageRoot').innerHTML=`<div class="page-head"><div><h1>Messages</h1><p>Internal university communication.</p></div><button class="btn btn-primary" id="newMessage">＋ New Message</button></div><div class="message-layout"><div class="card"><div class="section-title"><h3>Inbox</h3><span>${inbox.filter(x=>!x.read).length} unread</span></div>${inbox.map(m=>`<div class="list-item" data-msg="${m.id}"><div><b>${esc(m.subject)}</b><div class="muted">${esc(findRecord('users',m.from)?.name||m.from)}</div><small>${fmtDateTime(m.date)}</small></div>${m.read?'':'<span class="badge-status status-warning">New</span>'}</div>`).join('')||'<div class="empty">Inbox is empty.</div>'}</div><div class="card conversation"><div class="section-title"><h3>Conversation</h3></div><div class="empty">Select a message from your inbox to view it.</div></div></div>${messageModal(d,u)}`;setupGlobal();document.getElementById('newMessage').onclick=()=>openModal('msgModal');document.querySelectorAll('[data-msg]').forEach(b=>b.onclick=()=>{const m=findRecord('messages',b.dataset.msg);updateRecord('messages',m.id,{read:true});document.querySelector('.conversation').innerHTML=`<div class="section-title"><h3>${esc(m.subject)}</h3><small>${fmtDateTime(m.date)}</small></div><div class="bubble in">${esc(m.body)}</div><div class="actions" style="margin-top:auto"><button class="btn btn-secondary" onclick="openModal('msgModal')">Reply</button></div>`})}
function messageModal(d,u){const recipients=d.users.filter(x=>x.id!==u.id);return `<div class="modal" id="msgModal"><div class="modal-box"><div class="modal-head"><h3>New Message</h3><button class="close" data-close-modal="msgModal">×</button></div><div class="modal-body"><form id="msgForm"><div class="form-group"><label>Recipient</label><select name="to" class="form-control" required>${recipients.map(x=>`<option value="${x.id}">${esc(x.name)} — ${x.role}</option>`).join('')}</select></div><div class="form-group"><label>Subject</label><input name="subject" class="form-control" required></div><div class="form-group"><label>Message</label><textarea name="body" class="form-control" rows="6" required></textarea></div><div class="form-actions"><button class="btn btn-primary">Send Message</button></div></form></div></div></div>`}
document.addEventListener('submit',e=>{
 if(e.target.id==='assignmentForm'){e.preventDefault();const u=currentUser(),r=formData(e.target),c=findRecord('classes',r.class);try{const teacherId=u.role==='teacher'?u.teacherId:r.teacher;if(!teacherId)throw Error('Please select a teacher.');if(!c)throw Error('Please select a valid class.');const editId=e.target.dataset.editId;if(editId)updateRecord('assignments',editId,{...r,marks:Number(r.marks),semester:c.semester,program:c.program,teacher:teacherId,lateAllowed:r.lateAllowed==='true'});else createAssignment({...r,marks:Number(r.marks),semester:c.semester,program:c.program,teacher:teacherId,lateAllowed:r.lateAllowed==='true',status:'Published',created:todayISO()});toast(editId?'Assignment updated successfully.':'Assignment created successfully.');e.target.reset();delete e.target.dataset.editId;document.querySelector('#assignmentModal h3').textContent='Create Assignment';closeModal('assignmentModal');renderAssignments(u.role,u)}catch(err){toast(err.message,'error')}}
 if(e.target.id==='submissionForm'){e.preventDefault();const u=currentUser(),r=formData(e.target),s=getData('students').find(x=>x.id===u.studentId),a=findRecord('assignments',r.assignment);if(!s||!a)return toast('Unable to identify the student or assignment.','error');const deadline=new Date(`${a.dueDate}T${a.dueTime}`);if(deadline<new Date()&&!a.lateAllowed)return toast('The deadline has passed and late submissions are disabled.','error');const file=e.target.file.files[0];if(file&&file.size>5*1024*1024)return toast('File must be 5 MB or smaller.','error');submitAssignment({assignment:r.assignment,student:s.id,date:new Date().toISOString(),status:deadline<new Date()?'Late':'Submitted',fileName:file?.name||'',text:r.text,link:r.link,marks:null,feedback:'',reviewed:false});closeModal('submissionModal');renderAssignments('student',u)}
 if(e.target.id==='msgForm'){e.preventDefault();const u=currentUser(),r=formData(e.target);sendMessage({...r,from:u.id});closeModal('msgModal');renderMessages(u.role,u)}
})
function renderResults(role,u){
 const d=db(),cfg=d.settings||{}; let rows=d.results||[];
 if(role==='student')rows=rows.filter(r=>r.student===u.studentId&&r.published);
 if(role==='teacher')rows=rows.filter(r=>d.subjects.find(x=>x.id===r.subject)?.teacher===u.teacherId);
 const canManage=role==='admin'||role==='teacher';
 document.getElementById('pageRoot').innerHTML=`<div class="page-head"><div><h1>Results / Grades</h1><p>${canManage?'Create, calculate, review and publish academic results.':'View your published grades and GPA.'}</p></div>${canManage?'<button class="btn btn-primary" id="addResult">＋ Add Result</button>':''}</div>
 <div class="card"><div class="filters"><div class="filter-item"><input id="resultSearch" class="form-control" placeholder="Search student, subject…"></div><div class="filter-item"><select id="resultFilter" class="form-control"><option value="">All statuses</option><option value="published">Published</option><option value="draft">Draft</option></select></div></div>
 <div class="table-wrap"><table class="table"><thead><tr><th>Student</th><th>Subject</th><th>Quiz</th><th>Assignment</th><th>Midterm</th><th>Final</th><th>Total</th><th>%</th><th>Grade</th><th>GPA</th><th>Status</th>${canManage?'<th>Actions</th>':''}</tr></thead><tbody id="resultRows"></tbody></table></div><div id="resultPagination" class="pagination"></div></div>
 ${canManage?`<div class="modal" id="resultModal"><div class="modal-box"><div class="modal-head"><h3 id="resultModalTitle">Add Result</h3><button class="close" data-close-modal="resultModal">×</button></div><div class="modal-body"><form id="resultForm"><input type="hidden" name="id"><div class="form-grid"><div class="form-group"><label>Student</label><select id="resultStudent" name="student" class="form-control" required></select></div><div class="form-group"><label>Subject</label><select id="resultSubject" name="subject" class="form-control" required></select></div><div class="form-group"><label>Class</label><select id="resultClass" name="class" class="form-control"></select></div><div class="form-group"><label>Semester</label><input name="semester" type="number" min="1" max="8" class="form-control" required></div><div class="form-group"><label>Quiz</label><input name="quiz" type="number" min="0" max="100" value="0" class="form-control"></div><div class="form-group"><label>Assignment</label><input name="assignment" type="number" min="0" max="100" value="0" class="form-control"></div><div class="form-group"><label>Midterm</label><input name="midterm" type="number" min="0" max="100" value="0" class="form-control"></div><div class="form-group"><label>Final</label><input name="final" type="number" min="0" max="100" value="0" class="form-control"></div><div class="form-group full"><label>Remarks</label><textarea name="remarks" class="form-control" rows="3"></textarea></div><div class="form-group"><label><input type="checkbox" name="publish"> Publish result immediately</label></div></div><div class="form-actions"><button type="button" class="btn btn-light" data-close-modal="resultModal">Cancel</button><button class="btn btn-primary">Save Result</button></div></form></div></div></div>`:''}`;
 setupGlobal(); let page=1,size=Math.max(3,Number(cfg.pageSize)||8);
 const draw=()=>{const q=(document.getElementById('resultSearch').value||'').toLowerCase(),st=document.getElementById('resultFilter').value,filtered=rows.filter(r=>{const hay=`${studentName(r.student)} ${subjectName(r.subject)} ${r.grade} ${r.percentage}`.toLowerCase();return(!q||hay.includes(q))&&(!st||(st==='published'?r.published:!r.published))}),pages=Math.max(1,Math.ceil(filtered.length/size));if(page>pages)page=pages;const items=filtered.slice((page-1)*size,page*size);document.getElementById('resultRows').innerHTML=items.map(r=>`<tr><td>${esc(studentName(r.student))}</td><td>${esc(subjectName(r.subject))}</td><td>${r.quiz??0}</td><td>${r.assignment??0}</td><td>${r.midterm??0}</td><td>${r.final??0}</td><td>${r.total??0}</td><td>${r.percentage??0}%</td><td><b>${esc(r.grade||'—')}</b></td><td>${r.gpa??0}</td><td>${r.published?statusBadge('Published'):statusBadge('Draft')}</td>${canManage?`<td><div class="actions"><button class="btn btn-light btn-sm" data-result-edit="${r.id}">Edit</button>${r.published?'':'<button class="btn btn-secondary btn-sm" data-result-publish="'+r.id+'">Publish</button>'}</div></td>`:''}</tr>`).join('')||`<tr><td colspan="${canManage?12:11}"><div class="empty">No results found.</div></td></tr>`;renderPagination(document.getElementById('resultPagination'),pages,page,x=>{page=x;draw()});if(canManage){document.querySelectorAll('[data-result-edit]').forEach(b=>b.onclick=()=>openResult(b.dataset.resultEdit));document.querySelectorAll('[data-result-publish]').forEach(b=>b.onclick=()=>{const r=findRecord('results',b.dataset.resultPublish);if(!r)return;saveResult({...r,published:true},true);toast('Result published.');renderResults(role,u)})}};
 document.getElementById('resultSearch').oninput=()=>{page=1;draw()};document.getElementById('resultFilter').onchange=()=>{page=1;draw()};
 if(canManage){populateSelect('resultStudent',d.students,x=>`${x.id} — ${x.name}`,x=>x.id);const allowedSubjects=role==='teacher'?d.subjects.filter(x=>x.teacher===u.teacherId):d.subjects;populateSelect('resultSubject',allowedSubjects,x=>`${x.code} — ${x.name}`,x=>x.id);populateSelect('resultClass',role==='teacher'?d.classes.filter(x=>x.teacher===u.teacherId):d.classes,x=>x.name,x=>x.id);const form=document.getElementById('resultForm');function openResult(id){form.reset();form.elements.id.value=id||'';document.getElementById('resultModalTitle').textContent=id?'Edit Result':'Add Result';const r=id?findRecord('results',id):{};if(id){['student','subject','class','semester','quiz','assignment','midterm','final','remarks'].forEach(k=>{if(form.elements[k])form.elements[k].value=r[k]??''});form.elements.publish.checked=!!r.published}else{form.elements.semester.value=Number(d.settings?.semester?.match(/\d+/)?.[0]||4)}openModal('resultModal')}document.getElementById('addResult').onclick=()=>openResult(null);form.onsubmit=e=>{e.preventDefault();const r=formData(form),id=r.id;delete r.id;delete r.publish;r.quiz=Number(r.quiz||0);r.assignment=Number(r.assignment||0);r.midterm=Number(r.midterm||0);r.final=Number(r.final||0);r.semester=Number(r.semester||1);r.published=form.elements.publish.checked;try{if(!r.student||!r.subject)throw Error('Student and subject are required.');const calculated=calculateResult(r.quiz,r.assignment,r.midterm,r.final);if(id)updateRecord('results',id,{...r,...calculated});else saveResult(r,r.published);toast(r.published?'Result saved and published.':'Result saved as draft.');closeModal('resultModal');renderResults(role,u)}catch(err){toast(err.message,'error')}}}
 draw();
}
function renderAnnouncements(role,u){
 const d=db(),cfg=d.settings||{};let rows=(d.announcements||[]).slice().sort((a,b)=>String(b.date).localeCompare(String(a.date)));if(role==='student')rows=rows.filter(a=>a.status==='Published');
 const manage=role==='admin';document.getElementById('pageRoot').innerHTML=`<div class="page-head"><div><h1>Announcements</h1><p>University notices, academic updates and important communications.</p></div>${manage?'<button class="btn btn-primary" id="addAnnouncement">＋ New Announcement</button>':''}</div><div class="card"><div class="filters"><div class="filter-item"><input id="annSearch" class="form-control" placeholder="Search announcements…"></div><div class="filter-item"><select id="annPriority" class="form-control"><option value="">All priorities</option><option>Important</option><option>Normal</option></select></div></div><div class="grid grid-2" id="annList"></div><div id="annPagination" class="pagination"></div></div>${manage?`<div class="modal" id="annModal"><div class="modal-box"><div class="modal-head"><h3>New Announcement</h3><button class="close" data-close-modal="annModal">×</button></div><div class="modal-body"><form id="annForm"><div class="form-grid"><div class="form-group"><label>Title</label><input name="title" class="form-control" required></div><div class="form-group"><label>Priority</label><select name="priority" class="form-control"><option>Normal</option><option>Important</option></select></div><div class="form-group full"><label>Message</label><textarea name="message" class="form-control" rows="5" required></textarea></div><div class="form-group"><label>Audience</label><select name="audience" class="form-control"><option>All Students</option><option>All Teachers</option><option>Everyone</option></select></div><div class="form-group"><label>Expiry</label><input name="expiry" type="date" class="form-control"></div></div><div class="form-actions"><button type="button" class="btn btn-light" data-close-modal="annModal">Cancel</button><button class="btn btn-primary">Publish Announcement</button></div></form></div></div></div>`:''}`;setupGlobal();let page=1,size=Math.max(3,Number(cfg.pageSize)||6);const draw=()=>{const q=document.getElementById('annSearch').value.toLowerCase(),pr=document.getElementById('annPriority').value,filtered=rows.filter(a=>(!q||`${a.title} ${a.message}`.toLowerCase().includes(q))&&(!pr||a.priority===pr)),pages=Math.max(1,Math.ceil(filtered.length/size));if(page>pages)page=pages;const items=filtered.slice((page-1)*size,page*size);document.getElementById('annList').innerHTML=items.map(a=>`<article class="card"><div class="section-title"><span>${statusBadge(a.priority)}</span>${a.pinned?'<span class="muted">📌 Pinned</span>':''}</div><h3>${esc(a.title)}</h3><p>${esc(a.message)}</p><small class="muted">${fmtDate(a.date)}${a.expiry?' · Expires '+fmtDate(a.expiry):''}</small>${manage?`<div class="actions" style="margin-top:10px"><button class="btn btn-danger btn-sm" data-ann-del="${a.id}">Delete</button></div>`:''}</article>`).join('')||'<div class="empty" style="grid-column:1/-1">No announcements found.</div>';renderPagination(document.getElementById('annPagination'),pages,page,x=>{page=x;draw()});if(manage)document.querySelectorAll('[data-ann-del]').forEach(b=>b.onclick=()=>confirmAction('Delete this announcement?',()=>{deleteRecord('announcements',b.dataset.annDel);toast('Announcement deleted.');renderAnnouncements(role,u)}))};document.getElementById('annSearch').oninput=()=>{page=1;draw()};document.getElementById('annPriority').onchange=()=>{page=1;draw()};if(manage){document.getElementById('addAnnouncement').onclick=()=>openModal('annModal');document.getElementById('annForm').onsubmit=e=>{e.preventDefault();const r=formData(e.target);addRecord('announcements',{...r,date:todayISO(),status:'Published',pinned:false});toast('Announcement published.');closeModal('annModal');e.target.reset();renderAnnouncements(role,u)}}draw();
}
function renderNotifications(role,u){const ns=notificationsFor(u);document.getElementById('pageRoot').innerHTML=`<div class="page-head"><div><h1>Notifications</h1><p>Stay updated with assignments, results, fees and university notices.</p></div><button class="btn btn-light" id="markAll">Mark all as read</button></div><div class="card"><div class="list">${ns.map(n=>`<div class="list-item"><div><b>${esc(n.title)}</b><div>${esc(n.message)}</div><small class="muted">${esc(n.type)} · ${fmtDateTime(n.date)}</small></div><div class="actions">${n.read?'<span class="muted">Read</span>':'<button class="btn btn-light btn-sm" data-read="'+n.id+'">Mark read</button>'}<button class="btn btn-danger btn-sm" data-not-del="${n.id}">Delete</button></div></div>`).join('')||'<div class="empty">No notifications.</div>'}</div></div>`;document.getElementById('markAll').onclick=()=>markAllRead(u);document.querySelectorAll('[data-read]').forEach(b=>b.onclick=()=>{markNotificationRead(b.dataset.read);renderNotifications(role,u)});document.querySelectorAll('[data-not-del]').forEach(b=>b.onclick=()=>deleteNotification(b.dataset.notDel))}
function renderReports(role,u){const d=db();const cards=[['Students',d.students.length],['Teachers',d.teachers.length],['Attendance',d.attendance.length],['Assignments',d.assignments.length],['Results',d.results.length],['Fees',d.fees.reduce((a,x)=>a+Number(x.amount),0).toLocaleString()]];document.getElementById('pageRoot').innerHTML=`<div class="page-head"><div><h1>Reports</h1><p>Operational and academic reporting centre.</p></div></div><div class="grid grid-3">${cards.map(x=>`<div class="card stat"><div class="stat-icon">📊</div><div><h3>${x[1]}</h3><p>${x[0]}</p></div></div>`).join('')}</div><div class="card" style="margin-top:16px"><div class="section-title"><h3>Export Reports</h3></div><div class="actions"><button class="btn btn-primary" data-report="students">Student Enrollment</button><button class="btn btn-secondary" data-report="attendance">Attendance</button><button class="btn btn-secondary" data-report="fees">Fee Collection</button><button class="btn btn-secondary" data-report="results">Results</button><button class="btn btn-light" id="printReport">Print</button></div></div><div class="grid grid-2" style="margin-top:16px"><div class="card"><h3>Department-wise Students</h3>${d.departments.map(dep=>{const n=d.students.filter(s=>s.department===dep.name).length;return `<div style="margin:12px 0"><div class="section-title"><span>${esc(dep.name)}</span><b>${n}</b></div><div class="progress"><span style="width:${Math.min(100,n*22)}%"></span></div></div>`}).join('')}</div><div class="card"><h3>Monthly Admissions</h3>${chartBars([30,45,55,63,74,86],['Mar','Apr','May','Jun','Jul','Aug'])}</div></div>`;document.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>{const rows=reportRows(b.dataset.report);csvDownload(b.dataset.report+'-report.csv',[['Report generated',new Date().toLocaleString()],[],...rows])});document.getElementById('printReport').onclick=()=>printSection('EAD University Report',document.querySelector('.page-head').parentElement.innerHTML)}
function renderSettings(role,u){
 const s={pageSize:8,searchEnabled:true,filtersEnabled:true,lateSubmission:true,defaultView:'table',passkeyEnabled:true,
   theme:'light',accentColor:'#0d9488',density:'comfortable',borderRadius:16,fontScale:100,sidebarWidth:260,animations:true,compactTables:false,
   allowUserManagement:true,allowUserCreation:true,allowRoleEditing:true,requireActiveUser:true,notificationsEnabled:true,messagesEnabled:true,auditLogging:true,autoSaveSettings:true,
   ...(getData('settings')||{})};
 const checked=k=>s[k]!==false?'checked':'';
 document.getElementById('pageRoot').innerHTML=`
 <div class="page-head"><div><h1>Settings & Configuration</h1><p>Configure the portal's appearance, user management and system behaviour without changing the existing academic workflows.</p></div></div>
 <div class="grid grid-2">
  <div class="card">
   <div class="section-title"><h3>General Configuration</h3><span class="status-badge status-active">Live settings</span></div>
   <form id="settingsForm">
    <div class="form-grid">
     <div class="form-group"><label>University Name</label><input name="university" class="form-control" value="${esc(s.university||'EAD UNIVERSITY')}"></div>
     <div class="form-group"><label>Academic Year</label><input name="academicYear" class="form-control" value="${esc(s.academicYear||'2026')}"></div>
     <div class="form-group"><label>Current Semester</label><input name="semester" class="form-control" value="${esc(s.semester||'Fall 2026')}"></div>
     <div class="form-group"><label>Attendance Warning %</label><input name="attendanceWarning" type="number" min="1" max="100" class="form-control" value="${s.attendanceWarning}"></div>
     <div class="form-group"><label>Rows / cards per page</label><input name="pageSize" type="number" min="3" max="50" class="form-control" value="${s.pageSize}"></div>
     <div class="form-group"><label>Max document size (MB)</label><input name="materialMaxFileSizeMB" type="number" min="1" max="50" class="form-control" value="${s.materialMaxFileSizeMB||10}"></div>
     <div class="form-group"><label>Default data view</label><select name="defaultView" class="form-control"><option value="table" ${s.defaultView==='table'?'selected':''}>Table</option><option value="board" ${s.defaultView==='board'?'selected':''}>Board</option></select></div>
    </div>
    <hr class="settings-divider">
    <h3>Design & Theme</h3>
    <div class="form-grid">
     <div class="form-group"><label>Theme</label><select name="theme" class="form-control"><option value="light" ${s.theme!=='dark'?'selected':''}>Light</option><option value="dark" ${s.theme==='dark'?'selected':''}>Dark</option></select></div>
     <div class="form-group"><label>Accent colour</label><input name="accentColor" type="color" class="form-control" value="${/^#[0-9a-fA-F]{6}$/.test(s.accentColor||'')?s.accentColor:'#0d9488'}"></div>
     <div class="form-group"><label>Interface density</label><select name="density" class="form-control"><option value="comfortable" ${s.density!=='compact'?'selected':''}>Comfortable</option><option value="compact" ${s.density==='compact'?'selected':''}>Compact</option></select></div>
     <div class="form-group"><label>Border radius (px)</label><input name="borderRadius" type="number" min="6" max="28" class="form-control" value="${s.borderRadius}"></div>
     <div class="form-group"><label>Font scale (%)</label><input name="fontScale" type="number" min="85" max="120" class="form-control" value="${s.fontScale}"></div>
     <div class="form-group"><label>Sidebar width (px)</label><input name="sidebarWidth" type="number" min="220" max="340" class="form-control" value="${s.sidebarWidth}"></div>
    </div>
    <div class="settings-checks">
     <label><input name="animations" type="checkbox" ${checked('animations')}> Enable interface animations</label>
     <label><input name="compactTables" type="checkbox" ${checked('compactTables')}> Use compact table rows</label>
    </div>
    <hr class="settings-divider">
    <h3>User Management</h3>
    <div class="settings-checks">
     <label><input name="allowUserManagement" type="checkbox" ${checked('allowUserManagement')}> Enable user management controls</label>
     <label><input name="allowUserCreation" type="checkbox" ${checked('allowUserCreation')}> Allow adding new users</label>
     <label><input name="allowRoleEditing" type="checkbox" ${checked('allowRoleEditing')}> Allow role/status editing</label>
     <label><input name="requireActiveUser" type="checkbox" ${checked('requireActiveUser')}> Require active users for portal access</label>
    </div>
    <hr class="settings-divider">
    <h3>System Functionalities</h3>
    <div class="settings-checks">
     <label><input name="searchEnabled" type="checkbox" ${checked('searchEnabled')}> Enable dynamic search</label>
     <label><input name="filtersEnabled" type="checkbox" ${checked('filtersEnabled')}> Enable dynamic filters</label>
     <label><input name="lateSubmission" type="checkbox" ${checked('lateSubmission')}> Allow late submissions</label>
     <label><input name="passkeyEnabled" type="checkbox" ${checked('passkeyEnabled')}> Enable passkey authentication</label>
     <label><input name="notificationsEnabled" type="checkbox" ${checked('notificationsEnabled')}> Enable notifications</label>
     <label><input name="messagesEnabled" type="checkbox" ${checked('messagesEnabled')}> Enable messaging</label>
     <label><input name="auditLogging" type="checkbox" ${checked('auditLogging')}> Enable audit logging</label>
     <label><input name="autoSaveSettings" type="checkbox" ${checked('autoSaveSettings')}> Automatically persist configuration</label>
     <label><input name="materialUploadsEnabled" type="checkbox" ${checked('materialUploadsEnabled')}> Enable Learning Materials uploads</label>
    </div>
    <div class="form-actions"><button class="btn btn-primary">Save Configuration</button><button type="button" class="btn btn-light" id="resetSettings">Restore Defaults</button></div>
   </form>
  </div>
  <div class="card">
   <div class="section-title"><h3>Data Management</h3><span class="muted">Safe local backup</span></div>
   <p class="muted">Export the complete portal dataset or restore the original demo data. Existing workflows and records remain unchanged.</p>
   <div class="actions"><button class="btn btn-secondary" id="backup">Backup Data</button><button class="btn btn-warning" id="resetData">Reset Demo Data</button></div>
   <hr class="settings-divider">
   <h3>Current Configuration</h3>
   <div class="list">
    <div class="list-item"><span>Theme</span><b>${s.theme==='dark'?'Dark':'Light'}</b></div>
    <div class="list-item"><span>Accent</span><b>${esc(s.accentColor||'#0d9488')}</b></div>
    <div class="list-item"><span>Pagination</span><b>${s.pageSize} rows/cards</b></div>
    <div class="list-item"><span>Search / Filters</span><b>${s.searchEnabled!==false?'On':'Off'} / ${s.filtersEnabled!==false?'On':'Off'}</b></div>
    <div class="list-item"><span>Default View</span><b>${s.defaultView==='board'?'Board':'Table'}</b></div>
    <div class="list-item"><span>User Management</span><b>${s.allowUserManagement!==false?'Enabled':'Disabled'}</b></div>
    <div class="list-item"><span>Passkeys</span><b>${s.passkeyEnabled!==false?'Enabled':'Disabled'}</b></div>
    <div class="list-item"><span>Notifications / Messages</span><b>${s.notificationsEnabled!==false?'On':'Off'} / ${s.messagesEnabled!==false?'On':'Off'}</b></div>
   </div>
  </div>
 </div>`;
 const form=document.getElementById('settingsForm');
 const collect=()=>{
   const r=formData(form);
   ['animations','compactTables','allowUserManagement','allowUserCreation','allowRoleEditing','requireActiveUser','searchEnabled','filtersEnabled','lateSubmission','passkeyEnabled','notificationsEnabled','messagesEnabled','auditLogging','autoSaveSettings'].forEach(k=>r[k]=form[k].checked);
   r.pageSize=Math.min(50,Math.max(3,Number(r.pageSize)||8));
   r.materialMaxFileSizeMB=Math.min(50,Math.max(1,Number(r.materialMaxFileSizeMB)||10));
   r.attendanceWarning=Math.min(100,Math.max(1,Number(r.attendanceWarning)||75));
   r.borderRadius=Math.min(28,Math.max(6,Number(r.borderRadius)||16));
   r.fontScale=Math.min(120,Math.max(85,Number(r.fontScale)||100));
   r.sidebarWidth=Math.min(340,Math.max(220,Number(r.sidebarWidth)||260));
   r.theme=r.theme==='dark'?'dark':'light';
   r.accentColor=/^#[0-9a-fA-F]{6}$/.test(r.accentColor)?r.accentColor:'#0d9488';
   r.universityName=r.university;
   return {...s,...r};
 };
 form.onsubmit=e=>{e.preventDefault();const next=collect();saveData('settings',next);localStorage.setItem('eadTheme',next.theme);applyPortalConfiguration?.();window.dispatchEvent(new Event('ead-config-change'));toast('Configuration saved and applied successfully.');setTimeout(()=>renderSettings(role,u),80)};
 document.getElementById('resetSettings').onclick=()=>confirmAction('Restore all configuration options to their defaults?',()=>{
   const current=getData('settings')||{}; const defaults={university:'EAD UNIVERSITY',universityName:'EAD UNIVERSITY',academicYear:'2026',semester:'Fall 2026',attendanceWarning:75,lateSubmission:true,pageSize:8,searchEnabled:true,filtersEnabled:true,defaultView:'table',passkeyEnabled:true,theme:'light',accentColor:'#0d9488',density:'comfortable',borderRadius:16,fontScale:100,sidebarWidth:260,animations:true,compactTables:false,allowUserManagement:true,allowUserCreation:true,allowRoleEditing:true,requireActiveUser:true,notificationsEnabled:true,messagesEnabled:true,auditLogging:true,autoSaveSettings:true,materialMaxFileSizeMB:10,materialAllowedTypes:'pdf,doc,docx,ppt,pptx,xls,xlsx,txt',materialUploadsEnabled:true};
   saveData('settings',{...current,...defaults});localStorage.setItem('eadTheme','light');applyPortalConfiguration?.();window.dispatchEvent(new Event('ead-config-change'));renderSettings(role,u);toast('Configuration defaults restored.');
 });
 document.getElementById('backup').onclick=()=>{const blob=new Blob([JSON.stringify(db(),null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='ead-university-backup.json';a.click();toast('Backup exported successfully.')};
 document.getElementById('resetData').onclick=()=>confirmAction('Reset all local data to the original demo dataset?',()=>resetDemoData());
}
function renderProfile(role,u){
 const d=db(),record=role==='student'?d.students.find(x=>x.id===u.studentId):role==='teacher'?d.teachers.find(x=>x.id===u.teacherId):u;
 const photoKey='eadProfilePhoto_'+u.id,photo=localStorage.getItem(photoKey)||'';
 const avatar=photo?`<img src="${photo}" alt="Profile picture" class="profile-picture" id="profileImagePreview">`:`<div class="avatar profile-picture" id="profileImagePreview">${initials(record.name)}</div>`;
 document.getElementById('pageRoot').innerHTML=`<div class="page-head"><div><h1>My Profile</h1><p>Account and permitted personal information.</p></div></div><div class="grid grid-2"><div class="card"><div class="profile-picture-container"><div id="profilePictureWrap">${avatar}</div><div><label class="upload-button">📷 Add / Change Photo<input type="file" id="profilePhotoInput" accept="image/*" hidden></label><div class="upload-note">PNG, JPG or WEBP. Image is stored locally for this prototype.</div></div></div><hr style="border:0;border-top:1px solid var(--border);margin:18px 0"><h2 style="margin:0">${esc(record.name)}</h2><p class="muted">${esc(role)} · ${esc(record.id||u.id)}</p><div class="list"><div class="list-item"><span>Email</span><b>${esc(record.email)}</b></div><div class="list-item"><span>Department</span><b>${esc(record.department||'Administration')}</b></div>${record.program?`<div class="list-item"><span>Program</span><b>${esc(record.program)}</b></div>`:''}${record.semester?`<div class="list-item"><span>Semester</span><b>${record.semester}</b></div>`:''}<div class="list-item"><span>Status</span>${statusBadge(record.status)}</div></div></div><div class="card"><h3>Update Profile</h3><form id="profileForm"><div class="form-group"><label>Phone</label><input name="phone" class="form-control" value="${esc(record.phone||'')}"></div><div class="form-group"><label>Address</label><textarea name="address" class="form-control" rows="3">${esc(record.address||'')}</textarea></div>${role==='teacher'?`<div class="form-group"><label>Office Room</label><input name="office" class="form-control" value="${esc(record.office||'')}"></div>`:''}<div class="form-group"><label>New Password (optional)</label><input name="password" type="password" class="form-control" minlength="6"></div><div class="form-actions"><button class="btn btn-primary">Save Changes</button></div></form><div class="passkey-setup" style="margin-top:22px;padding-top:18px;border-top:1px solid var(--border)"><h3 style="margin:0 0 6px">Passkey Sign-In</h3><p class="muted" style="font-size:13px">Add this device as a secure passkey. You can then use fingerprint, face recognition, or your device screen lock at sign-in.</p><button type="button" class="btn btn-light" id="registerPasskey">🔑 Set Up Passkey</button><p class="muted" id="passkeySetupNote" style="font-size:12px;margin-bottom:0"></p></div></div></div>`;
 document.getElementById('profilePhotoInput').onchange=e=>{const file=e.target.files?.[0];if(!file)return;if(!file.type.startsWith('image/'))return toast('Please select a valid image file.','error');if(file.size>2*1024*1024)return toast('Image must be 2 MB or smaller.','error');const reader=new FileReader();reader.onload=ev=>{localStorage.setItem(photoKey,ev.target.result);document.getElementById('profilePictureWrap').innerHTML=`<img src="${ev.target.result}" alt="Profile picture" class="profile-picture" id="profileImagePreview">`;toast('Profile picture updated successfully.');};reader.readAsDataURL(file)};
 document.getElementById('profileForm').onsubmit=e=>{e.preventDefault();const r=formData(e.target);if(r.password&&r.password.length<6)return toast('Password must be at least 6 characters.','error');if(role==='admin')updateRecord('users',u.id,r);else updateRecord(role==='student'?'students':'teachers',record.id,r);toast('Profile updated successfully.');};
 if(getData('settings')?.passkeyEnabled===false){document.getElementById('registerPasskey')?.remove()}
document.getElementById('registerPasskey')?.addEventListener('click',async()=>{const note=document.getElementById('passkeySetupNote');try{if(!window.PublicKeyCredential)throw new Error('This browser does not support passkeys.');const currentPassword=window.prompt('For security, enter your current portal password to add a passkey:');if(!currentPassword)return;note.textContent='Preparing secure passkey registration…';const accountEmail=record.email||u.email;const r=await fetch('/api/auth/passkey/register/options',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:accountEmail,password:currentPassword,role})});const out=await r.json();if(!r.ok)throw new Error(out.error||'Unable to start passkey setup.');const opts=out.options;const fromB64=v=>Uint8Array.from(atob(v.replace(/-/g,'+').replace(/_/g,'/')+('='.repeat((4-(v.length%4))%4))),c=>c.charCodeAt(0));const toB64=b=>btoa(String.fromCharCode(...new Uint8Array(b))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');opts.challenge=fromB64(opts.challenge);opts.user.id=fromB64(opts.user.id);opts.excludeCredentials=(opts.excludeCredentials||[]).map(c=>({...c,id:fromB64(c.id)}));const cred=await navigator.credentials.create({publicKey:opts});const payload={id:cred.id,rawId:toB64(cred.rawId),type:cred.type,response:{clientDataJSON:toB64(cred.response.clientDataJSON),attestationObject:toB64(cred.response.attestationObject),transports:cred.response.getTransports?cred.response.getTransports():[]},clientExtensionResults:cred.getClientExtensionResults?cred.getClientExtensionResults():{}};const verify=await fetch('/api/auth/passkey/register/verify',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({userId:out.userId,transactionId:out.transactionId,response:payload})});const verified=await verify.json();if(!verify.ok)throw new Error(verified.error||'Passkey verification failed.');note.textContent='Passkey added successfully. You can now use it on the login page.';toast('Passkey registered successfully.');}catch(ex){note.textContent=ex.name==='TypeError'?'Passkey setup needs the EAD server running (npm start) and this page must be opened from that server.':(ex.message||'Passkey setup failed. Use HTTPS or localhost.');toast(note.textContent,'error')}});
}
function renderCourses(role,u){const d=db(),s=d.students.find(x=>x.id===u.studentId),cls=d.classes.filter(c=>c.students.includes(s.id));document.getElementById('pageRoot').innerHTML=`<div class="page-head"><div><h1>My Courses</h1><p>Enrolled subjects, teachers and schedules.</p></div></div><div class="grid grid-3">${cls.map(c=>{const sub=findRecord('subjects',c.subject);return `<div class="card course-card"><span class="course-code">${esc(sub.code)}</span><h3>${esc(sub.name)}</h3><p class="muted">${esc(sub.program)} · Semester ${sub.semester}</p><div class="list"><div class="list-item"><span>Teacher</span><b>${esc(teacherName(c.teacher))}</b></div><div class="list-item"><span>Credits</span><b>${sub.credits}</b></div><div class="list-item"><span>Room</span><b>${esc(c.room)}</b></div><div class="list-item"><span>Class</span><b>${esc(c.name)}</b></div></div><div class="actions" style="margin-top:12px"><a class="btn btn-light btn-sm" href="assignments.html">Assignments</a><a class="btn btn-light btn-sm" href="attendance.html">Attendance</a></div></div>`}).join('')||'<div class="card empty">No enrolled courses.</div>'}</div>`}
function renderStudentTeachers(role,u){const d=db(),s=d.students.find(x=>x.id===u.studentId),cls=d.classes.filter(c=>c.students.includes(s.id)),ids=[...new Set(cls.map(c=>c.teacher))];document.getElementById('pageRoot').innerHTML=`<div class="page-head"><div><h1>My Teachers</h1><p>Faculty assigned to your courses.</p></div></div><div class="grid grid-3">${ids.map(id=>{const t=findRecord('teachers',id);return `<div class="card"><div style="display:flex;gap:12px;align-items:center"><div class="avatar" style="width:55px;height:55px">${initials(t.name)}</div><div><h3 style="margin:0">${esc(t.name)}</h3><p class="muted">${esc(t.designation)}</p></div></div><p>${esc(t.department)} · Office ${esc(t.office)}</p><div class="actions"><a class="btn btn-primary btn-sm" href="messages.html">Message</a></div></div>`}).join('')||'<div class="card empty">No assigned teachers.</div>'}</div>`}
function renderTeacherStudents(role,u){const d=db(),cls=d.classes.filter(c=>c.teacher===u.teacherId),ids=[...new Set(cls.flatMap(c=>c.students))];document.getElementById('pageRoot').innerHTML=`<div class="page-head"><div><h1>Students</h1><p>Students enrolled in your assigned classes.</p></div></div><div class="card"><div class="filters"><input id="tsSearch" class="top-search" style="display:block;width:280px" placeholder="Search students…"></div><div class="table-wrap"><table class="table"><thead><tr><th>ID</th><th>Name</th><th>Program</th><th>Semester</th><th>Attendance</th><th>Actions</th></tr></thead><tbody id="tsRows">${ids.map(id=>{const s=findRecord('students',id),a=attendanceStats(id);return `<tr data-global-text><td>${id}</td><td>${esc(s.name)}</td><td>${esc(s.program)}</td><td>${s.semester}</td><td>${a.pct<d.settings.attendanceWarning?statusBadge('Warning'):statusBadge('Good')} ${a.pct}%</td><td><a class="btn btn-light btn-sm" href="messages.html">Message</a></td></tr>`}).join('')}</tbody></table></div></div>`;document.getElementById('tsSearch').oninput=e=>document.querySelectorAll('#tsRows tr').forEach(r=>r.style.display=r.textContent.toLowerCase().includes(e.target.value.toLowerCase())?'':'none')}
function renderPlaceholder(role,u,p){document.getElementById('pageRoot').innerHTML=`<div class="card empty"><h2>${esc(p.replaceAll('-',' '))}</h2><p>This module is available through the shared EAD University portal data layer.</p></div>`}

function renderExams(role,u){const d=db();let ex=d.exams;if(role==='teacher'){const subs=d.subjects.filter(s=>s.teacher===u.teacherId).map(s=>s.id);ex=ex.filter(e=>subs.includes(e.subject))}if(role==='student'){const s=d.students.find(x=>x.id===u.studentId);ex=ex.filter(e=>d.classes.find(c=>c.id===e.class)?.students.includes(s.id))}
document.getElementById('pageRoot').innerHTML=`<div class="page-head"><div><h1>Exams</h1><p>Schedules, rooms, instructions and status.</p></div>${role==='admin'?'<button class="btn btn-primary" id="addExam">＋ Create Exam</button>':''}</div><div class="grid grid-3">${ex.map(e=>`<div class="card"><div class="section-title"><span>${statusBadge(e.status)}</span><span class="muted">${fmtDate(e.date)}</span></div><h3>${esc(e.name)}</h3><p>${esc(subjectName(e.subject))}</p><div class="list"><div class="list-item"><span>Time</span><b>${e.start}–${e.end}</b></div><div class="list-item"><span>Room</span><b>${esc(e.room)}</b></div><div class="list-item"><span>Total Marks</span><b>${e.total}</b></div><div class="list-item"><span>Class</span><b>${esc(className(e.class))}</b></div></div>${role==='admin'?`<div class="actions" style="margin-top:10px"><button class="btn btn-danger btn-sm" data-exdel="${e.id}">Delete</button></div>`:''}</div>`).join('')||'<div class="card empty">No exams scheduled.</div>'}</div>${role==='admin'?examModal():''}`;setupGlobal();if(role==='admin'){document.getElementById('addExam').onclick=()=>openModal('examModal');populateSelect('examSubject',d.subjects,x=>`${x.code} — ${x.name}`,x=>x.id);populateSelect('examClass',d.classes,x=>x.name,x=>x.id);document.getElementById('examForm').onsubmit=e=>{e.preventDefault();const r=formData(e.target);if(r.end<=r.start)return toast('End time must be after start time.','error');const x=addRecord('exams',{...r,total:Number(r.total),status:'Scheduled'});d.users.filter(x=>x.role==='student'||x.role==='teacher').forEach(user=>makeNotification(user.id,'Exam Scheduled',`${x.name} is scheduled for ${fmtDate(x.date)}.`,'Exam'));toast('Exam created successfully.');closeModal('examModal');renderExams(role,u)};document.querySelectorAll('[data-exdel]').forEach(b=>b.onclick=()=>confirmAction('Delete this exam?',()=>{deleteRecord('exams',b.dataset.exdel);toast('Exam deleted.');renderExams(role,u)}))}}
function examModal(){return `<div class="modal" id="examModal"><div class="modal-box"><div class="modal-head"><h3>Create Exam</h3><button class="close" data-close-modal="examModal">×</button></div><div class="modal-body"><form id="examForm"><div class="form-grid"><div class="form-group"><label>Exam Name</label><input name="name" class="form-control" required></div><div class="form-group"><label>Subject</label><select name="subject" id="examSubject" class="form-control" required></select></div><div class="form-group"><label>Date</label><input name="date" type="date" min="${todayISO()}" class="form-control" required></div><div class="form-group"><label>Start Time</label><input name="start" type="time" class="form-control" required></div><div class="form-group"><label>End Time</label><input name="end" type="time" class="form-control" required></div><div class="form-group"><label>Room</label><input name="room" class="form-control" required></div><div class="form-group"><label>Class</label><select name="class" id="examClass" class="form-control" required></select></div><div class="form-group"><label>Total Marks</label><input name="total" type="number" min="1" class="form-control" required></div><div class="form-group full"><label>Instructions</label><textarea name="instructions" class="form-control" rows="3"></textarea></div></div><div class="form-actions"><button class="btn btn-primary">Schedule Exam</button></div></form></div></div></div>`}
function renderFees(role,u){const d=db();let fs=d.fees;if(role==='student')fs=fs.filter(f=>f.student===u.studentId);const summary=role==='student'?feeTotal(u.studentId):{total:d.fees.reduce((a,x)=>a+Number(x.amount),0),paid:d.fees.filter(x=>x.status==='Paid').reduce((a,x)=>a+Number(x.amount),0),pending:d.fees.filter(x=>x.status!=='Paid'&&x.status!=='Waived').reduce((a,x)=>a+Number(x.amount),0)};document.getElementById('pageRoot').innerHTML=`<div class="page-head"><div><h1>Fees</h1><p>Fee records, payment status and outstanding balance.</p></div>${role==='admin'?'<button class="btn btn-primary" id="addFee">＋ Add Fee Record</button>':''}</div><div class="grid grid-3"><div class="card stat"><div class="stat-icon">💰</div><div><h3>Rs. ${summary.total.toLocaleString()}</h3><p>Total Fees</p></div></div><div class="card stat"><div class="stat-icon">✓</div><div><h3>Rs. ${summary.paid.toLocaleString()}</h3><p>Paid</p></div></div><div class="card stat"><div class="stat-icon">⏳</div><div><h3>Rs. ${summary.pending.toLocaleString()}</h3><p>Outstanding</p></div></div></div><div class="card" style="margin-top:16px"><div class="section-title"><h3>${role==='student'?'My Fee Records':'Fee Records'}</h3><button class="btn btn-light btn-sm" id="feePrint">Print Voucher</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Student</th><th>Fee Type</th><th>Amount</th><th>Due Date</th><th>Status</th><th>Payment Date</th><th>Transaction</th>${role==='admin'?'<th>Action</th>':''}</tr></thead><tbody>${fs.map(f=>`<tr><td>${esc(studentName(f.student))}</td><td>${esc(f.type)}</td><td>Rs. ${Number(f.amount).toLocaleString()}</td><td>${fmtDate(f.dueDate)}</td><td>${statusBadge(f.status)}</td><td>${fmtDate(f.paymentDate)}</td><td>${esc(f.transaction||'—')}</td>${role==='admin'?`<td><button class="btn btn-danger btn-sm" data-feedel="${f.id}">Delete</button></td>`:''}</tr>`).join('')||'<tr><td colspan="8"><div class="empty">No fee records.</div></td></tr>'}</tbody></table></div></div>${role==='admin'?feeModal(d):''}`;setupGlobal();document.getElementById('feePrint').onclick=()=>printSection('EAD University Fee Voucher',document.querySelector('.table-wrap').innerHTML);if(role==='admin'){document.getElementById('addFee').onclick=()=>openModal('feeModal');populateSelect('feeStudent',d.students,x=>`${x.id} — ${x.name}`,x=>x.id);document.getElementById('feeForm').onsubmit=e=>{e.preventDefault();const r=formData(e.target);if(Number(r.amount)<=0)return toast('Fee amount must be greater than zero.','error');addRecord('fees',{...r,amount:Number(r.amount)});const user=d.users.find(x=>x.studentId===r.student);if(user)makeNotification(user.id,r.status==='Overdue'?'Fee Overdue':'Fee Due',`${r.type} of Rs. ${Number(r.amount).toLocaleString()} is ${r.status.toLowerCase()}.`,'Fees');toast('Fee record added successfully.');closeModal('feeModal');renderFees(role,u)};document.querySelectorAll('[data-feedel]').forEach(b=>b.onclick=()=>confirmAction('Delete this fee record?',()=>{deleteRecord('fees',b.dataset.feedel);toast('Fee record deleted.');renderFees(role,u)}))}}
function feeModal(d){return `<div class="modal" id="feeModal"><div class="modal-box"><div class="modal-head"><h3>Add Fee Record</h3><button class="close" data-close-modal="feeModal">×</button></div><div class="modal-body"><form id="feeForm"><div class="form-grid"><div class="form-group"><label>Student</label><select name="student" id="feeStudent" class="form-control" required></select></div><div class="form-group"><label>Program</label><select name="program" class="form-control">${d.programs.map(p=>`<option>${esc(p.name)}</option>`).join('')}</select></div><div class="form-group"><label>Semester</label><input name="semester" type="number" min="1" max="8" class="form-control" required></div><div class="form-group"><label>Fee Type</label><select name="type" class="form-control"><option>Tuition Fee</option><option>Admission Fee</option><option>Examination Fee</option><option>Library Fee</option><option>Transport Fee</option><option>Hostel Fee</option><option>Miscellaneous Fee</option></select></div><div class="form-group"><label>Amount</label><input name="amount" type="number" min="1" class="form-control" required></div><div class="form-group"><label>Due Date</label><input name="dueDate" type="date" class="form-control" required></div><div class="form-group"><label>Status</label><select name="status" class="form-control"><option>Pending</option><option>Paid</option><option>Overdue</option><option>Partially Paid</option><option>Waived</option></select></div><div class="form-group"><label>Payment Date</label><input name="paymentDate" type="date" class="form-control"></div><div class="form-group"><label>Payment Method</label><input name="method" class="form-control"></div><div class="form-group"><label>Transaction ID</label><input name="transaction" class="form-control"></div><div class="form-group full"><label>Remarks</label><textarea name="remarks" class="form-control"></textarea></div></div><div class="form-actions"><button class="btn btn-primary">Add Fee Record</button></div></form></div></div></div>`}

function renderSubjects(role,u){if(role!=='admin'){const d=db(),subs=d.subjects.filter(s=>role==='teacher'?s.teacher===u.teacherId:false);document.getElementById('pageRoot').innerHTML=`<div class="page-head"><div><h1>My Subjects</h1><p>Subjects assigned to you.</p></div></div><div class="grid grid-3">${subs.map(s=>`<div class="card course-card"><span class="course-code">${s.code}</span><h3>${esc(s.name)}</h3><p>${esc(s.program)} · Semester ${s.semester}</p><div class="list"><div class="list-item"><span>Credits</span><b>${s.credits}</b></div><div class="list-item"><span>Type</span><b>${esc(s.type)}</b></div><div class="list-item"><span>Students</span><b>${d.classes.filter(c=>c.subject===s.id&&c.teacher===u.teacherId).reduce((a,c)=>a+c.students.length,0)}</b></div></div><div class="actions" style="margin-top:10px"><a class="btn btn-light btn-sm" href="attendance.html">Attendance</a><a class="btn btn-light btn-sm" href="assignments.html">Assignments</a><a class="btn btn-light btn-sm" href="results.html">Results</a></div></div>`).join('')||'<div class="card empty">No assigned subjects.</div>'}</div>`;return}renderGenericAdmin('subjects')}
function renderClasses(role,u){if(role!=='admin'){const d=db(),cls=d.classes.filter(c=>role==='teacher'?c.teacher===u.teacherId:false);document.getElementById('pageRoot').innerHTML=`<div class="page-head"><div><h1>My Classes</h1><p>Classes and enrolled rosters assigned to you.</p></div></div><div class="grid grid-2">${cls.map(c=>`<div class="card"><div class="section-title"><h3>${esc(c.name)}</h3>${statusBadge(c.status)}</div><p>${esc(subjectName(c.subject))} · ${esc(c.room)}</p><div class="kpi-row"><div class="kpi">Students <b>${c.students.length}</b></div><div class="kpi">Capacity <b>${c.capacity}</b></div><div class="kpi">Semester <b>${c.semester}</b></div></div><div class="table-wrap" style="margin-top:10px"><table class="table" style="min-width:400px"><thead><tr><th>ID</th><th>Student</th><th>Status</th></tr></thead><tbody>${c.students.map(id=>{const s=findRecord('students',id);return `<tr><td>${id}</td><td>${esc(s?.name||id)}</td><td>${statusBadge(s?.status||'Active')}</td></tr>`}).join('')}</tbody></table></div></div>`).join('')||'<div class="card empty">No assigned classes.</div>'}</div>`;return}renderGenericAdmin('classes')}

function renderMaterials(role,u){
 const root=document.getElementById('pageRoot'), d=db(), rows=(d.materials||[]);
 const isAdmin=role==='admin', canManage=isAdmin||role==='teacher';
 const subjects=d.subjects||[];
 const visible=role==='student'?rows.filter(x=>!x.roles||x.roles.includes('student')):rows;
 root.innerHTML=`<div class="page-head"><div><h1>Learning Materials</h1><p>Documents and study resources shared through the EAD portal.</p></div>
 ${canManage?'<button class="btn btn-primary" id="addMaterial">+ Add Document</button>':''}</div>
 <div class="card"><div class="filters" style="margin-bottom:16px"><input id="materialSearch" class="form-control" placeholder="Search documents..." style="max-width:320px"><select id="materialSubject" class="form-control" style="max-width:220px"><option value="">All subjects</option>${subjects.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('')}</select></div>
 <div id="materialList" class="grid grid-2"></div></div>
 <div class="modal" id="materialModal" aria-hidden="true"><div class="modal-box"><div class="modal-head"><h3>Add Document</h3><button class="close" id="closeMaterial">×</button></div>
 <div class="modal-body"><form id="materialForm"><div class="form-grid"><div class="form-group"><label>Title</label><input class="form-control" name="title" required></div>
 <div class="form-group"><label>Subject</label><select class="form-control" name="subject">${subjects.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('')}</select></div>
 <div class="form-group"><label>Description</label><textarea class="form-control" name="description" rows="3"></textarea></div>
 <div class="form-group"><label>Audience</label><select class="form-control" name="audience"><option value="student">Students</option><option value="all">Students & Teachers</option></select></div>
 <div class="form-group"><label>Document</label><input class="form-control" name="file" type="file" accept=".pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.txt" required></div></div>
 <div class="form-actions"><button class="btn btn-primary">Upload Document</button></div></form></div></div></div>`;
 const list=document.getElementById('materialList'), search=document.getElementById('materialSearch'), subj=document.getElementById('materialSubject');
 function draw(){const q=search.value.toLowerCase(),sv=subj.value;const rs=visible.filter(x=>(!q||`${x.title} ${x.description||''} ${x.fileName||''}`.toLowerCase().includes(q))&&(!sv||x.subject===sv));
 list.innerHTML=rs.length?rs.map(x=>`<article class="card" style="padding:18px"><div class="section-title"><h3>📄 ${esc(x.title)}</h3>${statusBadge('Available')}</div><p class="muted">${esc(x.description||'Study document')}<br><b>${esc(subjectName(x.subject))}</b> · ${esc(x.fileName||'Document')}</p><div class="actions"><a class="btn btn-secondary" href="${esc(x.url||'#')}" target="_blank">Open</a>${canManage?`<button class="btn btn-light" data-del-material="${esc(x.id)}">Delete</button>`:''}</div></article>`).join(''):'<div class="empty">No documents available.</div>';
 list.querySelectorAll('[data-del-material]').forEach(b=>b.onclick=()=>confirmAction('Delete this document?',()=>{deleteRecord('materials',b.dataset.delMaterial);draw();toast('Document removed.');}));
 }
 search.oninput=draw;subj.onchange=draw;draw();
 if(canManage){document.getElementById('addMaterial').onclick=()=>openModal('materialModal');document.getElementById('closeMaterial').onclick=()=>closeModal('materialModal');
 document.getElementById('materialForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),file=fd.get('file');if(!file?.name)return;
 const max=((d.settings||{}).materialMaxFileSizeMB||10)*1024*1024;if(file.size>max){toast(`File is larger than ${max/1024/1024} MB.`,'error');return}
 let upload={url:'',filename:'',originalName:file.name,size:file.size};try{const token=sessionStorage.getItem('eadApiToken');const r=await fetch('/api/uploads',{method:'POST',headers:token?{Authorization:`Bearer ${token}`}:{},body:(()=>{const x=new FormData();x.append('file',file);return x})()});if(r.ok)upload=await r.json();}catch(_){}
 addRecord('materials',{title:fd.get('title'),subject:fd.get('subject'),description:fd.get('description'),audience:fd.get('audience'),fileName:upload.originalName||file.name,url:upload.url||URL.createObjectURL(file),uploadedBy:u.id,date:new Date().toISOString()});
 closeModal('materialModal');e.target.reset();draw();toast('Document added successfully.');};}
}
